                opacity: 0,
                scale: 0.7,
              }}
              animate={{
                opacity: 1,
                scale: 1,
              }}
              className="
                w-full
                max-w-md
                bg-white
                rounded-[32px]
                shadow-xl
                border
                border-slate-200
                p-10
                text-center
              "
            >
              <motion.div
                initial={{
                  scale: 0,
                  rotate: -180,
                }}
                animate={{
                  scale: 1,
                  rotate: 0,
                }}
                transition={{
                  type: 'spring',
                  stiffness: 150,
                }}
                className="mb-6"
              >
                <CheckCircle2
                  size={80}
                  className="mx-auto text-green-500"
                />
              </motion.div>

              <h2 className="text-3xl font-bold text-slate-900">
                OTP Sent!
              </h2>

              <p className="text-slate-500 mt-3">
                A new verification code has
                been sent to your email.
              </p>

              <motion.button
                whileHover={{
                  y: -2,
                }}
                whileTap={{
                  scale: 0.98,
                }}
                className="
                  mt-8
                  w-full
                  h-12
                  rounded-xl
                  bg-blue-600
                  text-white
                  font-semibold
                "
              >
                Back to Verification
              </motion.button>

            </motion.div>
          )}

        </AnimatePresence>

      </div>
    </main>
  );
}

