              <ArrowLeft size={15} /> Back
            </motion.button>
          </Link>
          <div>
            <div className="flex flex-wrap items-center gap-2 mb-1">
              <div className="flex items-center gap-1.5">
                <ShieldAlert size={15} className="text-teal-400" />
                <span className="font-mono text-sm font-bold" style={{ color: "var(--da-teal)" }}>{e.id}</span>
              </div>
              <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-[11px] font-semibold ${PRIORITY_CLS[e.priority]}`}>{e.priority}</span>
              <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-[11px] font-semibold ${STATUS_CLS[e.status]}`}>{e.status}</span>
              <span className="text-[11px] text-[var(--color-text-muted)]">{e.daysOpen} days open · {e.subDistrict}</span>
            </div>
            <h1 className="text-base font-bold text-[var(--color-text-primary)] leading-snug max-w-2xl">{e.title}</h1>
          </div>
        </div>
        <motion.button type="button" whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}
          className="da-btn-secondary flex items-center gap-1.5 !h-9 !px-3 !text-xs shrink-0">
          <Download size={13} /> Export
        </motion.button>
      </motion.div>

      {/* Two-column layout */}
      <div className="grid grid-cols-1 gap-3 lg:grid-cols-3">

        {/* ── Left (2/3) ── */}
        <div className="flex flex-col gap-3 lg:col-span-2">

          {/* Case Summary */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.05 }}>
            <DashboardCard className="p-4 flex flex-col gap-3">
              <div className="flex items-center gap-2">
                <FileText size={14} className="text-teal-400" />
                <h3 className="text-sm font-bold text-[var(--color-text-primary)]">Case Summary</h3>
              </div>
              <p className="text-sm text-[var(--color-text-secondary)] leading-relaxed">{e.description}</p>
              <SlaBlock status={e.slaStatus} label={e.slaLabel} hours={e.slaHours} />
              <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                {[
                  { label: "Escalated On", value: e.escalatedOn   },
                  { label: "Days Open",    value: `${e.daysOpen}d` },
                  { label: "Category",     value: e.category      },
                  { label: "Sub-District", value: e.subDistrict   },
                ].map((m) => (
                  <div key={m.label} className="rounded-lg border px-3 py-2"
                    style={{ borderColor: "var(--color-border)", background: "var(--color-surface)" }}>
                    <div className="text-xs font-bold text-[var(--color-text-primary)]">{m.value}</div>
                    <div className="text-[10px] text-[var(--color-text-muted)] mt-0.5">{m.label}</div>
                  </div>
                ))}
              </div>
              <div className="flex items-center justify-between rounded-lg border px-3 py-2"
                style={{ borderColor: "rgba(20,184,166,0.25)", background: "rgba(20,184,166,0.06)" }}>
                <div className="flex items-center gap-2">
                  <Calendar size={12} className="text-teal-400" />
                  <span className="text-xs text-[var(--color-text-secondary)]">Expected Resolution</span>
                </div>
                <span className="text-xs font-bold text-teal-400">{e.expectedResolution}</span>
              </div>
            </DashboardCard>
          </motion.div>

          {storeEsc?.sourceComplaintId && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.07 }}>
              <DashboardCard className="p-4 flex items-center justify-between gap-3">
                <div className="text-xs text-[var(--color-text-secondary)]">
                  Source complaint{" "}
                  <Link
                    href={`/sub-district-admin/dashboard/complaints/${storeEsc.sourceComplaintId}`}
                    className="font-mono font-bold text-teal-400 hover:underline"
                  >
                    {storeEsc.sourceComplaintId}
                  </Link>
                  {" "}from {storeEsc.subDistrict}
                </div>
              </DashboardCard>
            </motion.div>
          )}

          {pendingResolution && pendingResolution.status === "Pending District Review" && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.08 }}>
              <DashboardCard className="p-4 flex flex-col gap-3">
                <div className="flex items-center gap-2">
                  <ClipboardCheck size={14} className="text-cyan-400" />
                  <h3 className="text-sm font-bold text-[var(--color-text-primary)]">Closure Request — {pendingResolution.id}</h3>
                </div>
                <p className="text-xs text-[var(--color-text-secondary)]">{pendingResolution.resolutionNotes}</p>
                {pendingResolution.workPerformed && (
                  <p className="text-[11px] text-[var(--color-text-muted)]">Work: {pendingResolution.workPerformed}</p>
                )}
                <div className="flex flex-wrap gap-2">
                  <button type="button" onClick={() => { approveResolution(pendingResolution.id); showToast("Closure approved — sub-district notified"); }}
                    className="rounded-lg px-3 py-1.5 text-xs font-semibold text-white" style={{ background: "#10b981" }}>
                    Approve Closure
                  </button>
                  <button type="button" onClick={() => { rejectResolution(pendingResolution.id, "Insufficient evidence"); showToast("Closure rejected"); }}
                    className="rounded-lg px-3 py-1.5 text-xs font-semibold border text-red-400" style={{ borderColor: "rgba(239,68,68,0.4)" }}>
                    Reject
                  </button>
                </div>
              </DashboardCard>
            </motion.div>
          )}

          {/* Location */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
            <DashboardCard className="p-4 flex flex-col gap-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <MapPin size={14} className="text-teal-400" />
                  <h3 className="text-sm font-bold text-[var(--color-text-primary)]">Location</h3>
                </div>
                <Link href="/district-admin/map"
                  className="flex items-center gap-1 text-[11px] font-medium hover:underline transition-colors"
                  style={{ color: "#14b8a6" }}>
                  Full Map →
                </Link>
              </div>
              <div className="grid grid-cols-1 gap-0 sm:grid-cols-2 sm:gap-x-6 divide-y divide-[var(--color-border)] sm:divide-y-0">
                {[
                  { label: "Address",      value: e.location     },
                  { label: "Coordinates",  value: e.coordinates  },
                  { label: "Sub-District", value: e.subDistrict  },
                  { label: "Zone",         value: e.zone         },
                ].map((r) => (
                  <div key={r.label} className="flex items-start justify-between gap-3 py-2 border-b border-[var(--color-border)] last:border-0 sm:border-b-0 sm:py-1.5">
                    <span className="text-[11px] text-[var(--color-text-muted)] shrink-0 w-24 pt-px">{r.label}</span>
                    <span className="text-[11px] text-[var(--color-text-primary)] font-medium text-right min-w-0 break-words">{r.value}</span>
                  </div>
                ))}
              </div>
              {/* Real interactive map */}
              <div className="rounded-xl overflow-hidden">
                <IndiaMap
                  adminRole="district_admin"
                  height="220px"
                  showBreadcrumb={false}
                  showControls={false}
                  showLegend={false}
                  showSidebar={false}
                  isDark
                />
              </div>
            </DashboardCard>
          </motion.div>

          {/* Activity Log + Add Note */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15 }}>
            <DashboardCard className="p-4 flex flex-col gap-3">
              <div className="flex items-center gap-2">
                <Activity size={14} className="text-teal-400" />
                <h3 className="text-sm font-bold text-[var(--color-text-primary)]">Activity Log</h3>
              </div>
              <div className="activity-timeline">
                <div className="da-activity-timeline-line activity-timeline-line" />
                <div className="activity-timeline-list">
                  {e.activityLog.map((entry, i) => (
                    <motion.div key={i} initial={{ opacity: 0, x: -6 }} animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.15 + i * 0.04 }} className="activity-timeline-item">
                      <div className={`activity-timeline-icon ${entry.actor === "System" ? "activity-timeline-icon-info" : "da-activity-timeline-icon-teal"}`}>
                        {entry.actor === "System" ? <Activity size={12} /> : <MessageSquare size={12} />}
                      </div>
                      <div className="activity-timeline-body">
                        <div className="activity-timeline-meta">
                          <span className="activity-timeline-title">{entry.actor}</span>
                          <span className="activity-timeline-time">{entry.time}</span>
                        </div>
                        <p className="activity-timeline-desc">{entry.action}</p>
                      </div>
                    </motion.div>
                  ))}
                </div>
              </div>
              {/* Add note — wired */}
              <div className="flex flex-col gap-2 pt-2 border-t border-[var(--color-border)]">
                <textarea rows={2} value={noteText} onChange={(e) => setNoteText(e.target.value)}
                  placeholder="Add an officer note or update…"
                  className="w-full rounded-lg border px-3 py-2 text-xs text-[var(--color-text-secondary)] bg-[var(--color-surface)] border-[var(--color-border)] resize-none focus:outline-none focus:border-teal-500/40 transition-colors" />
                <motion.button type="button" whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}
                  onClick={handleAddNote} disabled={!noteText.trim()}
                  className="self-end h-8 px-4 rounded-lg border text-xs font-medium transition-all disabled:opacity-40 disabled:cursor-not-allowed"
                  style={{ borderColor: "rgba(20,184,166,0.35)", background: noteText.trim() ? "rgba(20,184,166,0.1)" : "var(--color-surface)", color: "#14b8a6" }}>
                  Add Note
                </motion.button>
              </div>
            </DashboardCard>
          </motion.div>
        </div>

        {/* ── Right (1/3) ── */}
        <div className="flex flex-col gap-3">

          {/* Sticky Actions */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.06 }}>
            <StickyActions
              id={e.id} status={e.status} priority={e.priority} title={e.title}
              onAssign={handleAssign}
              onMarkInProgress={handleMarkInProgress}
              onUploadEvidence={handleUploadEvidence}
              onResolve={handleResolve}
              onEscalateFurther={handleEscalateFurther}
              onReject={handleReject}
              onRequestClarification={handleRequestClarification}
            />
          </motion.div>

          {/* Assignment */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.14 }}>
            <DashboardCard className="p-4 flex flex-col gap-3">
              <div className="flex items-center gap-2">
                <UserCheck size={14} className="text-teal-400" />
                <h3 className="text-sm font-bold text-[var(--color-text-primary)]">Assignment</h3>
              </div>
              <div className="flex flex-col divide-y divide-[var(--color-border)]">
                {[
                  { label: "Officer",    value: e.assignedTo,          highlight: true  },
                  { label: "Assigned",   value: e.assignedDate,      highlight: false },
                  { label: "Resolution", value: e.expectedResolution, highlight: false },
                  { label: "Supervisor", value: e.supervisor,        highlight: false },
                ].map((r) => (
                  <div key={r.label} className="flex items-center justify-between py-1.5 first:pt-0 last:pb-0">
                    <span className="text-[11px] text-[var(--color-text-muted)]">{r.label}</span>
                    <span className={`text-[11px] font-medium ${r.highlight ? "text-teal-400" : "text-[var(--color-text-primary)]"}`}>{r.value}</span>
                  </div>
                ))}
              </div>
            </DashboardCard>
          </motion.div>

          {/* Case Timeline */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.18 }}>
            <DashboardCard className="p-4 flex flex-col gap-2">
              <div className="flex items-center gap-2 mb-1">
                <Clock size={14} className="text-teal-400" />
                <h3 className="text-sm font-bold text-[var(--color-text-primary)]">Case Timeline</h3>
              </div>
              {e.timeline.map((step, i) => (
                <div key={i} className="flex gap-3 pb-2 last:pb-0">
                  <div className="flex flex-col items-center">
                    <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border"
                      style={{ borderColor: step.done ? "rgba(20,184,166,0.4)" : "var(--color-border)", background: step.done ? "rgba(20,184,166,0.1)" : "var(--color-surface)" }}>
                      {step.done ? <CheckCircle2 size={12} className="text-teal-400" /> : <Clock size={12} className="text-[var(--color-text-muted)]" />}
                    </div>
                    {i < e.timeline.length - 1 && (
                      <div className="w-px flex-1 mt-1 min-h-[12px]" style={{ background: step.done ? "rgba(20,184,166,0.3)" : "var(--color-border)" }} />
                    )}
                  </div>
                  <div className="pb-1 min-w-0">
                    <p className={`text-xs font-semibold ${step.done ? "text-[var(--color-text-primary)]" : "text-[var(--color-text-muted)]"}`}>{step.label}</p>
                    <p className="text-[10px] text-[var(--color-text-muted)] mt-0.5">{step.date}</p>
                    {step.note && <p className="text-[10px] text-[var(--color-text-secondary)] italic mt-0.5">{step.note}</p>}
                  </div>
                </div>
              ))}
            </DashboardCard>
          </motion.div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { motion } from "framer-motion";
import { DashboardCard } from "@/components/super-admin-dashboard/dashboard-card";
import {
  UserCircle, Shield, Bell, Settings, CheckCircle2,
  Eye, EyeOff, Save, Sun, Moon, Monitor, Check,
} from "lucide-react";
import { useThemeStore } from "@/stores/theme-store";

type TabId = "profile" | "security" | "notifications" | "preferences";

const TABS: { id: TabId; label: string; icon: typeof UserCircle }[] = [
  { id: "profile", label: "Profile", icon: UserCircle },
  { id: "security", label: "Security", icon: Shield },
  { id: "notifications", label: "Notifications", icon: Bell },
  { id: "preferences", label: "Preferences", icon: Settings },
];

function ThemePreferences() {
  const { mode, setMode } = useThemeStore();
  const options = [
    { value: "light"  as const, label: "Light",  icon: <Sun  size={16} /> },
    { value: "dark"   as const, label: "Dark",   icon: <Moon size={16} /> },
    { value: "system" as const, label: "System", icon: <Monitor size={16} /> },
  ];
  return (
    <div className="max-w-md">
      <p className="text-xs font-medium text-[var(--color-text-secondary)] mb-2">Appearance</p>
      <p className="text-[10px] text-[var(--color-text-muted)] mb-3">Synced with the header toggle — updates the whole app instantly.</p>
      <div className="flex gap-3">
        {options.map((t) => (
          <button key={t.value} type="button" onClick={() => setMode(t.value)}
            className="flex flex-col items-center gap-1.5 rounded-xl border px-5 py-3 text-xs font-medium transition-all"
            style={{
              borderColor: mode === t.value ? "var(--da-border-teal)" : "var(--color-border)",
              background:  mode === t.value ? "color-mix(in srgb, var(--da-teal) 8%, var(--color-surface))" : "var(--color-surface)",
              color:       mode === t.value ? "var(--da-teal)" : "var(--color-text-secondary)",
            }}>
            <span style={{ color: mode === t.value ? "var(--da-teal)" : "var(--color-text-muted)" }}>{t.icon}</span>
            {t.label}
            {mode === t.value && <Check size={10} className="text-teal-400" />}
          </button>
        ))}
      </div>
    </div>
  );
}

function ProfileContent() {
  const searchParams = useSearchParams();
  const tabParam = searchParams.get("tab") as TabId | null;
  const validTabs = TABS.map((t) => t.id);
  const initialTab: TabId = tabParam && validTabs.includes(tabParam) ? tabParam : "profile";

  const [activeTab, setActiveTab] = useState<TabId>(initialTab);
  const [saved, setSaved] = useState(false);
  const [showPwd, setShowPwd] = useState(false);

  const handleSave = () => {
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  };

  return (
    <div className="flex flex-col gap-4 max-w-4xl">
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex items-center gap-2"
      >
        <UserCircle size={20} className="text-teal-400 shrink-0" />
        <h1 className="text-lg font-bold text-[var(--color-text-primary)]">
          District Administrator Profile
        </h1>
      </motion.div>

      {/* Tabs */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.05 }}
      >
        <DashboardCard className="p-1 flex flex-wrap gap-1">
          {TABS.map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              type="button"
              onClick={() => setActiveTab(id)}
              className={`flex items-center gap-2 rounded-lg px-4 py-2.5 text-sm font-medium transition-all ${
                activeTab === id
                  ? "bg-teal-500/10 text-teal-300 border border-teal-500/20 shadow-[0_0_12px_rgba(20,184,166,0.1)]"
                  : "text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] border border-transparent"
              }`}
            >
              <Icon size={15} />
              {label}
            </button>
          ))}
        </DashboardCard>
      </motion.div>

      {/* Tab panels */}
      <motion.div
        key={activeTab}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.25 }}
      >
        {activeTab === "profile" && (
          <DashboardCard className="p-5">
            <h2 className="mb-4 text-sm font-semibold text-[var(--color-text-primary)]">Personal Information</h2>

            {/* Avatar row */}
            <div className="mb-5 flex items-center gap-4">
              <div
                className="flex h-16 w-16 shrink-0 items-center justify-center rounded-full border-2 text-2xl font-bold"
                style={{
                  borderColor: "var(--da-border-teal)",
                  background: "color-mix(in srgb, var(--da-teal) 12%, transparent)",
                  color: "var(--da-teal)",
                }}
              >
                D
              </div>
              <div>
                <p className="font-semibold text-[var(--color-text-primary)]">District Administrator</p>
                <p className="text-xs text-[var(--color-text-muted)]">DA-2026-DCO</p>
                <button type="button" className="mt-1 text-xs text-teal-400 hover:text-teal-300">
                  Change avatar
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              {[
                { label: "Full Name", placeholder: "District Administrator", value: "District Administrator" },
                { label: "Employee ID", placeholder: "DA-2026-DCO", value: "DA-2026-DCO" },
                { label: "Official Email", placeholder: "admin@district.gov.in", value: "admin@district.gov.in", type: "email" },
                { label: "Phone", placeholder: "+91 98765 00000", value: "+91 98765 00000", type: "tel" },
                { label: "District", placeholder: "Raigad District", value: "Raigad District" },
                { label: "Designation", placeholder: "District Collector", value: "District Collector" },
              ].map((f) => (
                <div key={f.label} className="flex flex-col gap-1.5">
                  <label className="text-xs font-medium text-[var(--color-text-secondary)]">{f.label}</label>
                  <input
                    type={f.type || "text"}
                    defaultValue={f.value}
                    className="h-10 rounded-lg border px-3 text-sm outline-none focus:border-teal-500/40 transition-colors"
                    style={{
                      borderColor: "var(--color-border)",
                      background: "var(--color-surface)",
                      color: "var(--color-text-primary)",
                    }}
                  />
                </div>
              ))}
            </div>
            <SaveButton saved={saved} onClick={handleSave} />
          </DashboardCard>
        )}

        {activeTab === "security" && (
          <DashboardCard className="p-5">
            <h2 className="mb-4 text-sm font-semibold text-[var(--color-text-primary)]">Security Settings</h2>
            <div className="flex flex-col gap-4 max-w-md">
              {[
                { label: "Current Password", placeholder: "••••••••" },
                { label: "New Password", placeholder: "••••••••" },
                { label: "Confirm New Password", placeholder: "••••••••" },
              ].map((f) => (
                <div key={f.label} className="flex flex-col gap-1.5">
                  <label className="text-xs font-medium text-[var(--color-text-secondary)]">{f.label}</label>
                  <div className="relative">
                    <input
                      type={showPwd ? "text" : "password"}
                      placeholder={f.placeholder}
                      className="h-10 w-full rounded-lg border px-3 pr-10 text-sm outline-none focus:border-teal-500/40"
                      style={{
                        borderColor: "var(--color-border)",
                        background: "var(--color-surface)",
                        color: "var(--color-text-primary)",
                      }}
                    />
                    <button
                      type="button"
                      onClick={() => setShowPwd((p) => !p)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)] hover:text-teal-400"
                    >
                      {showPwd ? <EyeOff size={14} /> : <Eye size={14} />}
                    </button>
                  </div>
                </div>
              ))}

              {/* 2FA toggle */}
              <div className="flex items-center justify-between rounded-lg border border-[var(--color-border)] bg-[var(--color-surface)] p-3">
                <div>
                  <p className="text-sm font-medium text-[var(--color-text-primary)]">Two-Factor Authentication</p>
                  <p className="text-xs text-[var(--color-text-muted)]">Secure your account with 2FA</p>
                </div>
                <div className="flex h-6 w-11 cursor-pointer rounded-full bg-teal-500/20 border border-teal-500/30 p-0.5">
                  <span className="h-5 w-5 translate-x-5 rounded-full bg-teal-400 transition-transform" />
                </div>
              </div>

              <SaveButton saved={saved} onClick={handleSave} />
            </div>
          </DashboardCard>
        )}

        {activeTab === "notifications" && (
          <DashboardCard className="p-5">
            <h2 className="mb-4 text-sm font-semibold text-[var(--color-text-primary)]">Notification Preferences</h2>
            <div className="flex flex-col gap-3 max-w-lg">
              {[
                { label: "New Escalation Raised", desc: "Alert when a new escalation is submitted", enabled: true },
                { label: "SLA Breach Warning", desc: "Alert when a complaint is nearing SLA deadline", enabled: true },
                { label: "Complaint Resolved", desc: "Notify when a complaint is marked resolved", enabled: false },
                { label: "Officer Activity", desc: "Updates from sub-district officers", enabled: true },
                { label: "Weekly Digest", desc: "Weekly district performance summary email", enabled: true },
                { label: "System Alerts", desc: "Platform maintenance and security notifications", enabled: false },
              ].map((n, i) => (
                <div
                  key={n.label}
                  className="flex items-center justify-between rounded-lg border border-[var(--color-border)] bg-[var(--color-surface)] p-3"
                >
                  <div>
                    <p className="text-sm font-medium text-[var(--color-text-primary)]">{n.label}</p>
                    <p className="text-xs text-[var(--color-text-muted)]">{n.desc}</p>
                  </div>
                  <div
                    className={`flex h-6 w-11 cursor-pointer rounded-full border p-0.5 transition-colors ${
                      n.enabled
                        ? "bg-teal-500/20 border-teal-500/30"
                        : "bg-[var(--color-border)] border-[var(--color-border)]"
                    }`}
                  >
                    <span
                      className={`h-5 w-5 rounded-full transition-transform ${
                        n.enabled ? "translate-x-5 bg-teal-400" : "translate-x-0 bg-[var(--color-text-muted)]"
                      }`}
                    />
                  </div>
                </div>
              ))}
              <SaveButton saved={saved} onClick={handleSave} />
            </div>
          </DashboardCard>
        )}

        {activeTab === "preferences" && (
          <DashboardCard className="p-5">
            <h2 className="mb-4 text-sm font-semibold text-[var(--color-text-primary)]">Dashboard Preferences</h2>
            <ThemePreferences />
            <div className="mt-6 border-t border-[var(--color-border)] pt-4 flex flex-col gap-4 max-w-md">
              {[
                { label: "Default Date Range", options: ["Today", "This Week", "This Month", "This Quarter"] },
                { label: "Map Default View", options: ["Risk View", "Report Density", "Resolution Rate"] },
                { label: "Table Rows Per Page", options: ["10", "25", "50", "100"] },
              ].map((pref) => (
                <div key={pref.label} className="flex flex-col gap-1.5">
                  <label className="text-xs font-medium text-[var(--color-text-secondary)]">{pref.label}</label>
                  <select
                    className="h-10 rounded-lg border px-3 text-sm outline-none"
                    style={{
                      borderColor: "var(--color-border)",
                      background: "var(--color-surface)",
                      color: "var(--color-text-primary)",
                    }}
                  >
                    {pref.options.map((o) => (
                      <option key={o} style={{ background: "var(--color-card)" }}>{o}</option>
                    ))}
                  </select>
                </div>
              ))}
              <SaveButton saved={saved} onClick={handleSave} />
            </div>
          </DashboardCard>
        )}
      </motion.div>
    </div>
  );
}

function SaveButton({
  saved,
  onClick,
}: {
  saved: boolean;
  onClick: () => void;
}) {
