            complaint={c}
            onClose={() => setEscalateOpen2(false)}
            onSubmit={(newEscId, priority, reason) => {
              setEscalateOpen2(false);
              handleEscalate(newEscId, priority, reason);
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

