          transition={{ duration: 0.8, ease: "easeOut" }}
          className="absolute z-50 pointer-events-none"
          style={{ left: x - 40, top: y - 40 }}
        >
          <ChevronUp size={80} className="text-[var(--color-amber)]" fill="var(--color-amber)" />
