function StatusProgressBar({ currentStep }: { currentStep: number }) {
  return (
    <div className="flex items-center gap-0">
      {STATUS_STEPS.map((label, i) => {
        const step = i + 1;
        const isCompleted = step <= currentStep;
        const isCurrent = step === currentStep;

        return (
          <div key={label} className="flex items-center">
            {/* Dot */}
            <div
              className="w-2 h-2 rounded-full shrink-0"
              style={{
                backgroundColor: isCompleted ? "var(--color-amber)" : "transparent",
                border: isCompleted ? "none" : "1.5px solid rgba(255,255,255,0.4)",
              }}
            />
            {/* Connector line */}
            {i < STATUS_STEPS.length - 1 && (
              <div
                className="w-5 h-[1.5px] mx-0.5"
                style={{ backgroundColor: step < currentStep ? "var(--color-amber)" : "rgba(255,255,255,0.2)" }}
              />
            )}
          </div>
        );
      })}
      {/* Current step label */}
      <span className="ml-2 text-[0.75rem] text-white/80 font-medium drop-shadow-[0_1px_2px_rgba(0,0,0,0.5)]">
        {STATUS_STEPS[currentStep - 1]}
      </span>
    </div>
  );
}

"use client";

import { useRef, useState, useEffect } from "react";
import { motion } from "framer-motion";
import { X, MessageCircle } from "lucide-react";
import { CommentItemRow } from "./CommentItem";
import { EmojiReactionBar } from "./EmojiReactionBar";
import { CommentInput } from "./CommentInput";
import type { ReportFeedItem, CommentItem } from "./types";

interface CommentsBottomSheetProps {
  report: ReportFeedItem;
  initialComments?: CommentItem[];
  onClose: () => void;
}

export function CommentsBottomSheet({ report, initialComments = [], onClose }: CommentsBottomSheetProps) {
  const sheetRef = useRef<HTMLDivElement>(null);
  const [comments, setComments] = useState<CommentItem[]>(initialComments);
  const [keyboardOpen, setKeyboardOpen] = useState(false);

  useEffect(() => {
    setComments(initialComments);
  }, [initialComments, report.id]);

  // Detect virtual keyboard via visualViewport resize
  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return;

    const handleResize = () => {
      const threshold = window.innerHeight * 0.75;
      setKeyboardOpen(vv.height < threshold);
    };

    vv.addEventListener("resize", handleResize);
    return () => vv.removeEventListener("resize", handleResize);
  }, []);

  const handleAddComment = (text: string) => {
    const newComment: CommentItem = {
      id: `new-${Date.now()}`,
      userName: "You",
      initial: "Y",
      color: "#F59E0B",
      text,
      likes: 0,
      timeAgo: "now",
      isOfficial: false,
      isPinned: false,
      replies: [],
    };
    setComments((prev) => [newComment, ...prev]);
  };

  const handleEmojiReact = (emoji: string) => {
    handleAddComment(emoji);
  };

  // Sort: pinned first
  const sortedComments = [
    ...comments.filter((c) => c.isPinned),
    ...comments.filter((c) => !c.isPinned),
  ];

  return (
    <>
      {/* Backdrop — fixed overlay, never affects feed scroll or layout */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40"
        style={{ touchAction: "none" }}
        onClick={onClose}
      />

      {/* Sheet — fixed position, isolated from feed flow */}
      <motion.div
        ref={sheetRef}
        initial={{ y: "100%" }}
        animate={{ y: 0 }}
        exit={{ y: "100%", transition: { duration: 0.18, ease: "easeIn" } }}
        transition={{
          type: "spring",
          stiffness: 400,
          damping: 40,
        }}
        className="fixed left-0 right-0 z-50 flex flex-col bg-[var(--color-card)] rounded-t-[20px]"
        style={{
          bottom: keyboardOpen
            ? "0px"
            : "calc(var(--bottom-nav-height, 60px) + env(safe-area-inset-bottom, 0px))",
          height: keyboardOpen ? "85dvh" : "calc(85dvh - var(--bottom-nav-height, 60px))",
          maxHeight: keyboardOpen ? "85dvh" : "calc(85dvh - var(--bottom-nav-height, 60px))",
          willChange: "transform",
          contain: "layout style",
        }}
      >
        {/* Drag handle */}
        <div className="flex items-center justify-center pt-2 pb-1 shrink-0">
          <div className="w-9 h-1 rounded-full bg-[var(--color-border)]" />
        </div>

        {/* Close button */}
        <button
          onClick={onClose}
          className="absolute right-4 top-4 w-8 h-8 rounded-full bg-[var(--color-surface)] flex items-center justify-center text-[var(--color-text-muted)] hover:text-[var(--color-text-primary)] transition-colors z-10"
        >
          <X size={18} />
        </button>

        {/* Header */}
        <div className="text-center pb-3 border-b border-[var(--color-border)] shrink-0">
          <h3 className="text-base font-bold text-[var(--color-text-primary)]" style={{ fontFamily: "var(--font-sans)" }}>
            Comments
            <span className="ml-1.5 text-[var(--color-text-muted)] font-normal text-sm">({report.comments})</span>
          </h3>
        </div>

        {/* Comments scroll area */}
        <div
          className="flex-1 overflow-y-auto px-4 py-3 space-y-3 min-h-0"
          style={{ WebkitOverflowScrolling: "touch" }}
        >
          {sortedComments.length > 0 ? (
            sortedComments.map((comment) => (
              <CommentItemRow key={comment.id} comment={comment} />
            ))
          ) : (
            <div className="py-12 text-center">
              <MessageCircle size={32} className="mx-auto text-[var(--color-text-muted)] mb-2" />
              <p className="text-xs text-[var(--color-text-muted)]">No comments yet. Start the conversation!</p>
            </div>
          )}
        </div>

        {/* Sticky bottom section — emoji + input, always visible above navbar */}
        <div className="shrink-0 mt-auto">
          {/* Emoji row */}
          <EmojiReactionBar onReact={handleEmojiReact} />

          {/* Comment input */}
          <CommentInput onSubmit={handleAddComment} />
        </div>
      </motion.div>
    </>
  );
}

"use client";

import { useState, useEffect, useCallback, type RefObject } from "react";
import { motion } from "framer-motion";
import { X } from "lucide-react";
import { CommentItemRow } from "./CommentItem";
import { EmojiReactionBar } from "./EmojiReactionBar";
import { CommentInput } from "./CommentInput";
import { SEVERITY_COLORS, SEVERITY_LABELS } from "./mockData";
import type { ReportFeedItem, CommentItem } from "./types";

interface CommentsPanelProps {
  report: ReportFeedItem;
  initialComments?: CommentItem[];
  reelRef: RefObject<HTMLDivElement | null>;
  onClose: () => void;
}

/**
 * Fixed-position comments panel that anchors itself relative to the reel
 * container without participating in the feed's flex/grid layout.
 * Opening/closing this component has ZERO effect on reel position.
 */
export function CommentsPanel({ report, initialComments = [], reelRef, onClose }: CommentsPanelProps) {
  const [comments, setComments] = useState<CommentItem[]>(initialComments);
  const [position, setPosition] = useState<{ top: number; left: number; height: number } | null>(null);
  const panelWidth = 380;
  const gap = 24;

  useEffect(() => {
    setComments(initialComments);
  }, [initialComments, report.id]);

  // Calculate position relative to the reel element
  const calcPosition = useCallback(() => {
    if (!reelRef.current) return;
    const rect = reelRef.current.getBoundingClientRect();
    const vw = window.innerWidth;

    // Space available on the right of the reel
    const spaceRight = vw - rect.right;
    // Space available on the left of the reel
    const spaceLeft = rect.left;

    let left: number;
    if (spaceRight >= panelWidth + gap) {
      // Place on the right
      left = rect.right + gap;
    } else if (spaceLeft >= panelWidth + gap) {
      // Place on the left
      left = rect.left - panelWidth - gap;
    } else {
      // Fallback: overlap slightly on the right
      left = vw - panelWidth - 16;
    }

    // Vertically center against the reel
    const reelCenterY = rect.top + rect.height / 2;
    const panelHeight = Math.min(rect.height * 0.9, 720);
    const top = Math.max(16, reelCenterY - panelHeight / 2);

    setPosition({ top, left, height: panelHeight });
  }, [reelRef]);

  // Calculate on mount and on resize
  useEffect(() => {
    calcPosition();
    window.addEventListener("resize", calcPosition);
    return () => window.removeEventListener("resize", calcPosition);
  }, [calcPosition]);

  const handleAddComment = (text: string) => {
    const newComment: CommentItem = {
      id: `new-${Date.now()}`,
      userName: "You",
      initial: "Y",
      color: "#F59E0B",
      text,
      likes: 0,
      timeAgo: "now",
      isOfficial: false,
      isPinned: false,
      replies: [],
    };
    setComments((prev) => [newComment, ...prev]);
  };

  const handleEmojiReact = (emoji: string) => {
    handleAddComment(emoji);
  };

  const sortedComments = [
    ...comments.filter((c) => c.isPinned),
    ...comments.filter((c) => !c.isPinned),
  ];

  // Don't render until position is calculated
  if (!position) return null;

  return (
    <motion.div
      initial={{ opacity: 0, x: 24, scale: 0.96 }}
      animate={{ opacity: 1, x: 0, scale: 1 }}
      exit={{ opacity: 0, x: 24, scale: 0.96 }}
      transition={{
        type: "spring",
        stiffness: 380,
        damping: 32,
        opacity: { duration: 0.15 },
      }}
      className="fixed z-50 flex flex-col"
      style={{
        top: position.top,
        left: position.left,
        width: panelWidth,
        height: position.height,
        borderRadius: "1.5rem",
        background: "var(--color-card)",
        border: "1px solid var(--color-border)",
        boxShadow: "0 12px 40px rgba(0,0,0,0.12), 0 4px 16px rgba(0,0,0,0.06)",
        willChange: "transform, opacity",
        contain: "layout style paint",
      }}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-3.5 border-b border-[var(--color-border)] shrink-0 rounded-t-[1.5rem]">
        <h3 className="text-sm font-bold text-[var(--color-text-primary)]" style={{ fontFamily: "var(--font-sans)" }}>
          Comments
          <span className="ml-1.5 text-[var(--color-text-muted)] font-normal text-xs">({report.comments})</span>
        </h3>
        <button
          onClick={onClose}
          className="w-8 h-8 rounded-full hover:bg-[var(--color-surface)] flex items-center justify-center text-[var(--color-text-secondary)] transition-colors"
          aria-label="Close comments"
        >
          <X size={18} />
        </button>
      </div>

      {/* Mini report preview */}
      <div className="flex items-center gap-3 px-5 py-3 border-b border-[var(--color-border)] shrink-0">
        <div
          className="w-[48px] h-[48px] rounded-xl shrink-0 overflow-hidden"
        >
          <img
            src={report.thumbnailUrl}
            alt={report.hazardType}
            className="w-full h-full object-cover"
          />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-[0.8rem] font-semibold text-[var(--color-text-primary)] line-clamp-2 leading-snug">
            {report.title}
          </p>
          <div className="flex items-center gap-2 mt-1">
            <span
              className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[0.6rem] font-medium"
              style={{ backgroundColor: `${SEVERITY_COLORS[report.severity]}15`, color: SEVERITY_COLORS[report.severity] }}
            >
              <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: SEVERITY_COLORS[report.severity] }} />
              {SEVERITY_LABELS[report.severity]}
            </span>
            <span className="text-[0.6rem] text-[var(--color-text-muted)]">{report.location}</span>
          </div>
        </div>
      </div>

      {/* Comments list */}
      <div
        className="flex-1 overflow-y-auto px-5 py-3 space-y-3 min-h-0"
        style={{ WebkitOverflowScrolling: "touch" }}
      >
        {sortedComments.length > 0 ? (
          sortedComments.map((comment) => (
            <CommentItemRow key={comment.id} comment={comment} />
          ))
        ) : (
          <div className="py-12 text-center">
            <p className="text-xs text-[var(--color-text-muted)]">No comments yet. Start the conversation!</p>
          </div>
        )}
      </div>

      {/* Emoji reaction bar */}
      <div className="shrink-0">
        <EmojiReactionBar onReact={handleEmojiReact} />
      </div>

      {/* Comment input */}
      <div className="shrink-0 rounded-b-[1.5rem]">
        <CommentInput onSubmit={handleAddComment} />
      </div>
    </motion.div>
  );
}

"use client";

import { useState, useCallback, useRef, useEffect } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { ChevronUp, ChevronDown } from "lucide-react";
import { useAuthStore } from "@/stores/authStore";
import { getCommunityFeed, getReportComments } from "@/lib/api/citizenApi";

import { FeedContainer } from "./FeedContainer";
import type { FeedContainerRef } from "./FeedContainer";
import { CommentsBottomSheet } from "./CommentsBottomSheet";
import { CommentsPanel } from "./CommentsPanel";
import type { ReportFeedItem, CommentItem } from "./types";

export function CommunityPage() {
  const email = useAuthStore((state) => state.user?.email);

  // State
  const [reports, setReports] = useState<ReportFeedItem[]>([]);
  const [commentReportId, setCommentReportId] = useState<string | null>(null);
  const [commentsByReport, setCommentsByReport] = useState<Record<string, CommentItem[]>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const feedRef = useRef<FeedContainerRef>(null);
  const reelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    async function loadFeed() {
      setIsLoading(true);
      setError(null);
      try {
        const data = await getCommunityFeed("district", email);
        setReports(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Unable to load community feed.");
        setReports([]);
      } finally {
        setIsLoading(false);
      }
    }

    void loadFeed();
  }, [email]);

  const activeCommentReport = commentReportId
    ? reports.find((r) => r.id === commentReportId) || null
    : null;

  // Auto-close comments when active post changes
  const handleIndexChange = useCallback((index: number) => {
    setCommentReportId(null);
  }, []);

  // Handlers
  const handleUpvote = useCallback((id: string) => {
    setReports((prev) =>
      prev.map((r) =>
        r.id === id
          ? { ...r, hasUpvoted: !r.hasUpvoted, upvotes: r.hasUpvoted ? r.upvotes - 1 : r.upvotes + 1 }
          : r
      )
    );
  }, []);

  const handleSave = useCallback((id: string) => {
    setReports((prev) =>
      prev.map((r) => (r.id === id ? { ...r, isSaved: !r.isSaved } : r))
    );
  }, []);

  const handleFollow = useCallback((id: string) => {
    setReports((prev) =>
      prev.map((r) => (r.id === id ? { ...r, isFollowing: !r.isFollowing } : r))
    );
  }, []);

  const handleComment = useCallback(async (id: string) => {
    setCommentReportId(id);
    if (commentsByReport[id]) return;

    try {
      const comments = await getReportComments(id, email);
      setCommentsByReport((prev) => ({ ...prev, [id]: comments }));
    } catch {
      setCommentsByReport((prev) => ({ ...prev, [id]: [] }));
    }
  }, [commentsByReport, email]);

  const handleShare = useCallback((_id: string) => {
    // Share logic placeholder
  }, []);

  const handleNavPrev = useCallback(() => {
    const idx = Math.max((feedRef.current?.currentIndex ?? 0) - 1, 0);
    feedRef.current?.scrollToIndex(idx);
  }, []);

  const handleNavNext = useCallback(() => {
    const max = (feedRef.current?.totalCount ?? 1) - 1;
    const idx = Math.min((feedRef.current?.currentIndex ?? 0) + 1, max);
    feedRef.current?.scrollToIndex(idx);
  }, []);

  return (
    <div className="relative h-full w-full overflow-x-hidden overflow-y-hidden bg-black lg:bg-[var(--color-page)]">
      {!isLoading && error && (
        <div className="absolute top-3 left-1/2 -translate-x-1/2 z-40 rounded-lg border border-red-500/40 bg-red-500/10 px-3 py-2 text-xs text-red-300">
          {error}
        </div>
      )}

      {!isLoading && reports.length === 0 && (
        <div className="absolute inset-0 z-20 flex items-center justify-center px-4">
          <p className="text-sm text-[var(--color-text-muted)]">No community reports available.</p>
        </div>
      )}

      {/* ─── Feed Container — NEVER changes when comments open ─── */}
      <div className="h-full w-full flex items-center justify-center">
        <div
          ref={reelRef}
          className="h-full w-full max-w-[380px] md:max-w-[420px] lg:max-w-[440px] xl:max-w-[480px] flex flex-col px-3 md:px-4 lg:px-0"
        >
          <div className="flex-1 min-h-0 overflow-hidden overflow-x-hidden">
            <FeedContainer
              ref={feedRef}
              reports={reports}
              onUpvote={handleUpvote}
              onComment={handleComment}
              onShare={handleShare}
              onSave={handleSave}
              onFollow={handleFollow}
              onIndexChange={handleIndexChange}
            />
          </div>
        </div>
      </div>

      {/* ─── Navigation Arrows (fixed, independent layer) ─── */}
      <div className="hidden md:flex flex-col gap-3 fixed top-1/2 -translate-y-1/2 z-30 right-4 lg:right-8">
        <motion.button
          onClick={handleNavPrev}
          whileHover={{ scale: 1.08 }}
          whileTap={{ scale: 0.95 }}
          className="w-10 h-10 lg:w-11 lg:h-11 rounded-full bg-[var(--color-card)] flex items-center justify-center border border-[var(--color-border)] opacity-80 hover:opacity-100 transition-opacity"
          style={{ boxShadow: "var(--shadow-neu)" }}
          aria-label="Previous post"
        >
          <ChevronUp size={18} className="text-[var(--color-text-secondary)]" />
        </motion.button>
        <motion.button
          onClick={handleNavNext}
          whileHover={{ scale: 1.08 }}
          whileTap={{ scale: 0.95 }}
          className="w-10 h-10 lg:w-11 lg:h-11 rounded-full bg-[var(--color-card)] flex items-center justify-center border border-[var(--color-border)] opacity-80 hover:opacity-100 transition-opacity"
          style={{ boxShadow: "var(--shadow-neu)" }}
          aria-label="Next post"
        >
          <ChevronDown size={18} className="text-[var(--color-text-secondary)]" />
        </motion.button>
      </div>

      {/* ─── Desktop Comments: FIXED layer, completely outside feed layout ─── */}
      <AnimatePresence>
        {activeCommentReport && (
          <div className="hidden lg:block">
            <CommentsPanel
              report={activeCommentReport}
              initialComments={commentsByReport[activeCommentReport.id] ?? []}
              reelRef={reelRef}
              onClose={() => setCommentReportId(null)}
            />
          </div>
        )}
      </AnimatePresence>

      {/* ─── Mobile: Bottom Sheet (fixed layer, unchanged) ─── */}
      <AnimatePresence>
        {activeCommentReport && (
          <div className="lg:hidden">
            <CommentsBottomSheet
              report={activeCommentReport}
              initialComments={commentsByReport[activeCommentReport.id] ?? []}
              onClose={() => setCommentReportId(null)}
            />
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useRef, useCallback, useEffect, useState, useImperativeHandle, forwardRef } from "react";
import { ReportCard } from "./ReportCard";
import type { ReportFeedItem } from "./types";

interface FeedContainerProps {
  reports: ReportFeedItem[];
  onUpvote: (id: string) => void;
  onComment: (id: string) => void;
  onShare: (id: string) => void;
  onSave: (id: string) => void;
  onFollow: (id: string) => void;
  onIndexChange?: (index: number) => void;
}

export interface FeedContainerRef {
  scrollToIndex: (index: number) => void;
  currentIndex: number;
  totalCount: number;
}

export const FeedContainer = forwardRef<FeedContainerRef, FeedContainerProps>(
  function FeedContainer({ reports, onUpvote, onComment, onShare, onSave, onFollow, onIndexChange }, ref) {
    const feedRef = useRef<HTMLDivElement>(null);
    const [currentIndex, setCurrentIndex] = useState(0);
    const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
    const prevIndexRef = useRef(0);

    // Keyboard navigation
    useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === "ArrowDown" || e.key === "ArrowUp") {
          e.preventDefault();
          const nextIndex = e.key === "ArrowDown"
            ? Math.min(currentIndex + 1, reports.length - 1)
            : Math.max(currentIndex - 1, 0);
          scrollToIndex(nextIndex);
        }
      };
      window.addEventListener("keydown", handleKeyDown);
      return () => window.removeEventListener("keydown", handleKeyDown);
    }, [currentIndex, reports.length]);

    // Track current card via IntersectionObserver
    useEffect(() => {
      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              const idx = cardRefs.current.indexOf(entry.target as HTMLDivElement);
              if (idx !== -1) setCurrentIndex(idx);
            }
          });
        },
        { threshold: 0.6, root: feedRef.current }
      );

      cardRefs.current.forEach((r) => {
        if (r) observer.observe(r);
      });

      return () => observer.disconnect();
    }, [reports.length]);

    // Notify parent when active index changes
    useEffect(() => {
      if (currentIndex !== prevIndexRef.current) {
        prevIndexRef.current = currentIndex;
        onIndexChange?.(currentIndex);
      }
    }, [currentIndex, onIndexChange]);

    const scrollToIndex = useCallback((index: number) => {
      cardRefs.current[index]?.scrollIntoView({ behavior: "smooth" });
      setCurrentIndex(index);
    }, []);

    const setCardRef = useCallback((el: HTMLDivElement | null, index: number) => {
      cardRefs.current[index] = el;
    }, []);

    // Expose navigation to parent
    useImperativeHandle(ref, () => ({
      scrollToIndex,
      currentIndex,
      totalCount: reports.length,
    }), [scrollToIndex, currentIndex, reports.length]);

    return (
      <div className="h-full w-full overflow-hidden overflow-x-hidden">
        <div
          ref={feedRef}
          className="h-full w-full overflow-y-scroll overflow-x-hidden snap-y snap-mandatory"
          style={{
            scrollbarWidth: "none",
            WebkitOverflowScrolling: "touch",
            overscrollBehaviorY: "contain",
          }}
        >
          {reports.map((report, i) => (
            <div
              key={report.id}
              ref={(el) => setCardRef(el, i)}
              className="snap-start snap-always h-full w-full shrink-0 py-2 lg:py-3"
            >
              <div className="h-full w-full rounded-2xl overflow-hidden">
                <ReportCard
                  report={report}
                  onUpvote={() => onUpvote(report.id)}
                  onComment={() => onComment(report.id)}
                  onShare={() => onShare(report.id)}
                  onSave={() => onSave(report.id)}
                  onFollow={() => onFollow(report.id)}
                />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }
);

"use client";

import { useRef, useState, useCallback } from "react";
import { ActionColumn, UpvoteBurst } from "./ActionColumn";
import { CardOverlay } from "./CardOverlay";
import type { ReportFeedItem } from "./types";

interface ReportCardProps {
  report: ReportFeedItem;
  onUpvote: () => void;
  onComment: () => void;
  onShare: () => void;
  onSave: () => void;
  onFollow: () => void;
}

export function ReportCard({ report, onUpvote, onComment, onShare, onSave, onFollow }: ReportCardProps) {
  const [doubleTap, setDoubleTap] = useState<{ show: boolean; x: number; y: number }>({ show: false, x: 0, y: 0 });
  const lastTapRef = useRef<number>(0);
  const cardRef = useRef<HTMLDivElement>(null);

  const handleTap = useCallback(
    (e: React.MouseEvent | React.TouchEvent) => {
      const now = Date.now();
      if (now - lastTapRef.current < 300) {
        // Double tap - upvote
        const rect = cardRef.current?.getBoundingClientRect();
        let clientX: number, clientY: number;
        if ("touches" in e) {
          clientX = e.changedTouches?.[0]?.clientX ?? 0;
          clientY = e.changedTouches?.[0]?.clientY ?? 0;
        } else {
          clientX = e.clientX;
          clientY = e.clientY;
        }
        const x = clientX - (rect?.left ?? 0);
        const y = clientY - (rect?.top ?? 0);
        setDoubleTap({ show: true, x, y });
        onUpvote();
        setTimeout(() => setDoubleTap({ show: false, x: 0, y: 0 }), 800);
        lastTapRef.current = 0;
      } else {
        lastTapRef.current = now;
      }
    },
    [onUpvote]
  );

  return (
    <div
      ref={cardRef}
      className="relative w-full flex-shrink-0 overflow-hidden"
      style={{ height: "100%", scrollSnapAlign: "start", scrollSnapStop: "always" }}
      onClick={handleTap}
    >
      {/* Media background */}
      <div className="absolute inset-0">
        {report.mediaType === "image" ? (
          <img
            src={report.mediaUrl}
            alt={report.title}
            className="w-full h-full object-cover"
          />
        ) : report.mediaType === "video" ? (
          <video
            src={report.mediaUrl}
            poster={report.thumbnailUrl}
            autoPlay
            muted
            loop
            playsInline
            className="w-full h-full object-cover"
          />
        ) : (
          /* Fallback: no media */
          <div className="w-full h-full bg-[var(--color-surface)] flex items-center justify-center">
            <div className="text-center">
              <span className="text-5xl block mb-2">{report.hazardEmoji}</span>
              <p className="text-sm text-[var(--color-text-muted)]">{report.location}</p>
            </div>
          </div>
        )}
      </div>

      {/* Gradient overlay (bottom) */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background: "linear-gradient(transparent 40%, rgba(0,0,0,0.85) 100%)",
        }}
      />

      {/* Double tap burst */}
      <UpvoteBurst show={doubleTap.show} x={doubleTap.x} y={doubleTap.y} />

      {/* Action column (right side) */}
      <ActionColumn
        report={report}
        onUpvote={onUpvote}
        onComment={onComment}
        onShare={onShare}
        onSave={onSave}
      />

      {/* Card overlay (bottom left) */}
      <CardOverlay report={report} onFollow={onFollow} />
    </div>
  );
}

