                  <p className="text-[10px] font-semibold text-[var(--color-text-muted)] uppercase tracking-wider px-2 mb-1">
                    Yesterday
                  </p>
                  <div className="space-y-0.5">{yesterdayItems.map(renderItem)}</div>
                </div>
              )}
              {earlierItems.length > 0 && (
