                  <div className="space-y-0.5">{earlierItems.map(renderItem)}</div>
                </div>
              )}
              {recent.length === 0 && (
                <div className="flex flex-col items-center justify-center py-8">
                  <Bell size={32} className="text-[var(--color-text-muted)] mb-2" />
