            </motion.div>
          )}
        </div>
      </div>

      {/* ── Right Detail Panel (desktop) ───────────────────────── */}
      <DesktopDetailPanel
        report={selectedReport}
        onClose={handleCloseDetail}
        onDelete={handleDelete}
        onToggleNotify={handleToggleNotify}
