      {/* ── Bottom Sheet Detail (mobile/tablet) ────────────────── */}
      <ReportDetailSheet
        report={selectedReport}
        onClose={handleCloseDetail}
        onDelete={handleDelete}
        onToggleNotify={handleToggleNotify}
      />
    </div>
  );
}

