                      <div
                        className="w-3 h-3 rounded-full border-2"
                        style={{
                          backgroundColor: isCompleted
                            ? report.status === "rejected" ? "var(--color-danger)" : "var(--color-amber)"
                            : "transparent",
                          borderColor: isCompleted
                            ? report.status === "rejected" ? "var(--color-danger)" : "var(--color-amber)"
                            : "var(--color-border)",
