                      />
                    )}
                  </div>
                  {/* Connector line */}
                  {i < totalSteps - 1 && (
                    <div
                      className="flex-1 h-0.5 mx-1"
                      style={{
                        backgroundColor: i < completedSteps - 1
                          ? report.status === "rejected" ? "var(--color-danger)" : "var(--color-amber)"
