"use client";

import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { WifiOff, Wifi, CloudUpload, Check } from "lucide-react";
import { getPendingReports, syncOfflineReports, type OfflineReport } from "@/lib/offlineDb";

/**
 * Offline sync status indicator.
 * Shows when:
 * - User is offline (with pending report count)
 * - Reports are being synced
 * - Sync completed successfully
 */
export function OfflineSyncStatus() {
  const [isOnline, setIsOnline] = useState(true);
  const [pendingCount, setPendingCount] = useState(0);
  const [syncing, setSyncing] = useState(false);
  const [syncResult, setSyncResult] = useState<{ synced: number; failed: number } | null>(null);

  // Check online status
  useEffect(() => {
    setIsOnline(navigator.onLine);

    const goOnline = () => setIsOnline(true);
    const goOffline = () => setIsOnline(false);

    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);

    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);

  // Check pending reports count
  useEffect(() => {
    const checkPending = async () => {
      const pending = await getPendingReports();
      setPendingCount(pending.length);
    };

    checkPending();
    const interval = setInterval(checkPending, 10000); // Check every 10s
    return () => clearInterval(interval);
  }, []);

  // Auto-sync when coming back online
  const handleSync = useCallback(async () => {
    if (pendingCount === 0 || syncing) return;

    setSyncing(true);
    setSyncResult(null);

    // Placeholder submit function — should be wired to actual API
    const submitFn = async (_report: OfflineReport): Promise<boolean> => {
      // TODO: Wire to actual report submission API
      const res = await fetch("/api/reports", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: _report.title,
          description: _report.description,
          category: _report.category,
          latitude: _report.latitude,
          longitude: _report.longitude,
        }),
      });
      return res.ok;
    };

    const result = await syncOfflineReports(submitFn);
    setSyncResult(result);
    setSyncing(false);

    // Refresh pending count
    const pending = await getPendingReports();
    setPendingCount(pending.length);

    // Clear success message after 5 seconds
    if (result.synced > 0) {
      setTimeout(() => setSyncResult(null), 5000);
    }
  }, [pendingCount, syncing]);

  // Auto-sync on online event
  useEffect(() => {
    const onOnline = () => {
      handleSync();
    };
    window.addEventListener("reckoning:online", onOnline);
    return () => window.removeEventListener("reckoning:online", onOnline);
  }, [handleSync]);

  // Don't render if all is well
  if (isOnline && pendingCount === 0 && !syncing && !syncResult) return null;

  return (
    <AnimatePresence mode="wait">
      {/* Offline indicator */}
      {!isOnline && (
        <motion.div
          key="offline"
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          className="flex items-center gap-2 px-3 py-2 rounded-xl bg-amber-500/10 border border-amber-500/20 text-sm"
        >
          <WifiOff size={14} className="text-amber-500 shrink-0" />
          <span className="text-[var(--color-text-primary)]">
            You&apos;re offline
            {pendingCount > 0 && (
              <span className="text-[var(--color-text-secondary)]">
                {" "}· {pendingCount} report{pendingCount !== 1 ? "s" : ""} queued
              </span>
            )}
          </span>
        </motion.div>
      )}

      {/* Syncing */}
      {isOnline && syncing && (
        <motion.div
          key="syncing"
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          className="flex items-center gap-2 px-3 py-2 rounded-xl bg-blue-500/10 border border-blue-500/20 text-sm"
        >
          <CloudUpload size={14} className="text-blue-500 shrink-0 animate-pulse" />
          <span className="text-[var(--color-text-primary)]">Syncing reports...</span>
        </motion.div>
      )}

      {/* Sync complete */}
      {isOnline && !syncing && syncResult && syncResult.synced > 0 && (
        <motion.div
          key="synced"
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          className="flex items-center gap-2 px-3 py-2 rounded-xl bg-emerald-500/10 border border-emerald-500/20 text-sm"
        >
          <Check size={14} className="text-emerald-500 shrink-0" />
          <span className="text-[var(--color-text-primary)]">
            {syncResult.synced} report{syncResult.synced !== 1 ? "s" : ""} synced
          </span>
        </motion.div>
      )}

      {/* Pending reports while online (manual sync) */}
      {isOnline && !syncing && !syncResult && pendingCount > 0 && (
        <motion.div
          key="pending"
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          className="flex items-center gap-2 px-3 py-2 rounded-xl bg-blue-500/10 border border-blue-500/20 text-sm"
        >
          <Wifi size={14} className="text-blue-500 shrink-0" />
          <span className="text-[var(--color-text-primary)]">
            {pendingCount} pending report{pendingCount !== 1 ? "s" : ""}
          </span>
          <button
            onClick={handleSync}
            className="ml-auto text-xs font-medium text-blue-600 dark:text-blue-400 hover:underline"
          >
            Sync now
          </button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { motion } from "framer-motion";
import { AlertTriangle, CheckCircle2, Sparkles, TriangleAlert } from "lucide-react";
import type { ReportAnalysisState } from "./reportTypes";

const STATUS_LINES = ["Scanning image…", "Detecting defects…", "Assessing severity…"];

interface AIAnalysisStepProps {
  analysisState: ReportAnalysisState;
  analysisStatusIndex: number;
  analysisError: string | null;
  previewUrl: string | null;
  onContinueManually: () => void;
  onDismissError: () => void;
}

export function AIAnalysisStep({
  analysisState,
  analysisStatusIndex,
  analysisError,
  previewUrl,
  onContinueManually,
  onDismissError,
}: AIAnalysisStepProps) {
  const statusLine = STATUS_LINES[analysisStatusIndex % STATUS_LINES.length];

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-5">
      <div className="overflow-hidden rounded-[1.75rem] border border-[var(--color-border)] bg-[var(--color-card)] p-4 shadow-[var(--shadow-neu)]">
        <div className="relative mx-auto aspect-[4/3] max-w-xl overflow-hidden rounded-[1.5rem] border border-[var(--color-border)] bg-[var(--color-surface)]">
          {previewUrl ? (
            <img src={previewUrl} alt="First uploaded evidence" className="h-full w-full object-cover" />
          ) : (
            <div className="flex h-full items-center justify-center text-[var(--color-text-muted)]">
              <Sparkles size={28} />
            </div>
          )}
          <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-[rgba(11,13,18,0.28)]" />
          <motion.div
            animate={{ opacity: [0.35, 0.95, 0.35], scale: [1, 1.02, 1] }}
            transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
            className="absolute inset-0 rounded-[1.5rem] border-2 border-[var(--color-amber)]"
          />
          <motion.div
            animate={{ y: ["12%", "78%", "12%"] }}
            transition={{ duration: 2.2, repeat: Infinity, ease: "easeInOut" }}
            className="absolute left-4 right-4 h-1 rounded-full bg-[color-mix(in_srgb,var(--color-amber)_45%,transparent)] shadow-[0_0_24px_rgba(245,158,11,0.6)]"
          />
          <div className="absolute left-4 top-4 inline-flex items-center gap-2 rounded-full bg-black/55 px-3 py-1.5 text-xs font-semibold text-white backdrop-blur">
            <Sparkles size={14} className="text-[var(--color-amber)]" />
            AI scanning
          </div>
        </div>
      </div>

      <div className="rounded-[1.75rem] border border-[var(--color-border)] bg-[var(--color-card)] p-4">
        <div className="flex items-center gap-3">
          <motion.div
            animate={{ scale: [1, 1.1, 1] }}
            transition={{ duration: 1.2, repeat: Infinity, ease: "easeInOut" }}
            className="flex h-10 w-10 items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--color-amber)_12%,transparent)] text-[var(--color-amber)]"
          >
            <Sparkles size={18} />
          </motion.div>
          <div>
            <p className="text-sm font-semibold text-[var(--color-text-primary)]">{statusLine}</p>
            <p className="text-xs text-[var(--color-text-muted)]">The analysis result will pre-fill the next step automatically.</p>
          </div>
        </div>
      </div>

      {analysisError && (
        <div className="rounded-[1.5rem] border border-[color-mix(in_srgb,var(--color-danger)_20%,transparent)] bg-[color-mix(in_srgb,var(--color-danger)_8%,transparent)] p-4">
          <div className="flex items-start gap-3">
            <TriangleAlert size={16} className="mt-0.5 shrink-0 text-[var(--color-danger)]" />
            <div className="flex-1">
              <p className="text-sm font-semibold text-[var(--color-danger)]">AI analysis unavailable</p>
              <p className="mt-1 text-xs text-[var(--color-danger)]">{analysisError}</p>
            </div>
            <button type="button" onClick={onDismissError} className="text-xs font-semibold text-[var(--color-danger)]">
              Dismiss
            </button>
          </div>
          <button type="button" onClick={onContinueManually} className="mt-4 inline-flex items-center gap-2 rounded-2xl border border-[var(--color-border)] bg-[var(--color-card)] px-4 py-2 text-sm font-semibold text-[var(--color-text-primary)]">
            <AlertTriangle size={14} />
            Continue manually
          </button>
        </div>
      )}

      {analysisState === "ready" && !analysisError && (
        <div className="flex items-center gap-3 rounded-[1.5rem] border border-[color-mix(in_srgb,var(--color-success)_20%,transparent)] bg-[color-mix(in_srgb,var(--color-success)_8%,transparent)] p-4">
          <CheckCircle2 size={18} className="text-[var(--color-success)]" />
          <div>
            <p className="text-sm font-semibold text-[var(--color-success)]">Analysis complete</p>
            <p className="text-xs text-[var(--color-text-muted)]">Your hazard fields are already pre-filled. Move to the next step.</p>
          </div>
        </div>
      )}
    </motion.div>
  );
}

"use client";

import { useCallback, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  Camera,
  FolderOpen,
  Upload,
  X,
  FileImage,
  FileVideo,
  TriangleAlert,
  Sparkles,
} from "lucide-react";
import {
  MAX_EVIDENCE_FILES,
  MAX_EVIDENCE_FILE_SIZE_BYTES,
  SUPPORTED_EVIDENCE_MIME_TYPES,
  type ReportAnalysisState,
  type ReportEvidenceFile,
  type SupportedEvidenceMimeType,
} from "./reportTypes";

const ACCEPT_ATTRIBUTE = SUPPORTED_EVIDENCE_MIME_TYPES.join(",");

interface EvidenceStepProps {
  touchDevice: boolean;
  evidenceFiles: ReportEvidenceFile[];
  analysisState: ReportAnalysisState;
  analysisError: string | null;
  onSelectFiles: (files: File[], source: "camera" | "gallery" | "drop") => void;
  onRemoveFile: (id: string) => void;
  onAnalyse: () => void;
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.05 } },
};

const itemVariants = {
  hidden: { opacity: 0, y: 12 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.28 } },
};

function isSupportedMimeType(value: string): value is SupportedEvidenceMimeType {
  return (SUPPORTED_EVIDENCE_MIME_TYPES as readonly string[]).includes(value);
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export function EvidenceStep({
  touchDevice,
  evidenceFiles,
  analysisState,
  analysisError,
  onSelectFiles,
  onRemoveFile,
  onAnalyse,
}: EvidenceStepProps) {
  const [isDragging, setIsDragging] = useState(false);
  const liveCaptureRef = useRef<HTMLInputElement>(null);
  const galleryRef = useRef<HTMLInputElement>(null);

  const canAddMore = evidenceFiles.length < MAX_EVIDENCE_FILES;
  const hasFiles = evidenceFiles.length > 0;
  const isBusy = analysisState === "uploading" || analysisState === "scanning";

  const handleFiles = useCallback(
    (files: FileList | File[], source: "camera" | "gallery" | "drop") => {
      onSelectFiles(Array.from(files), source);
      if (liveCaptureRef.current) {
        liveCaptureRef.current.value = "";
      }
      if (galleryRef.current) {
        galleryRef.current.value = "";
      }
    },
    [onSelectFiles],
  );

  const acceptedCountLabel = useMemo(
    () => `${evidenceFiles.length}/${MAX_EVIDENCE_FILES} files`,
    [evidenceFiles.length],
  );

  return (
    <motion.div variants={containerVariants} initial="hidden" animate="visible" className="space-y-6">
      {touchDevice ? (
        <motion.div variants={itemVariants} className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <button
            type="button"
            onClick={() => liveCaptureRef.current?.click()}
            disabled={!canAddMore || isBusy}
            className={`relative flex min-h-[140px] flex-col justify-between rounded-3xl border p-4 text-left transition-all ${
              canAddMore && !isBusy
                ? "border-[var(--color-amber)] bg-[color-mix(in_srgb,var(--color-amber)_8%,transparent)] hover:bg-[color-mix(in_srgb,var(--color-amber)_12%,transparent)]"
                : "border-[var(--color-border)] bg-[var(--color-surface)] opacity-60"
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="rounded-2xl bg-[color-mix(in_srgb,var(--color-amber)_14%,transparent)] p-3 text-[var(--color-amber)]">
                <Camera size={22} />
              </div>
              {evidenceFiles.length > 0 && (
                <span className="rounded-full bg-white/80 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.2em] text-[var(--color-text-secondary)]">
                  {acceptedCountLabel}
                </span>
              )}
            </div>
            <div>
              <h3 className="text-sm font-semibold text-[var(--color-text-primary)]">Live Capture</h3>
              <p className="mt-1 text-xs text-[var(--color-text-muted)]">Take Photo / Video</p>
              <p className="mt-2 text-xs text-[var(--color-text-secondary)]">Use your camera to capture the hazard right now.</p>
            </div>
            <input
              ref={liveCaptureRef}
              type="file"
              accept="image/*,video/*"
              capture="environment"
              multiple
              className="sr-only"
              onChange={(event) => {
                if (event.target.files?.length) {
                  handleFiles(event.target.files, "camera");
                }
              }}
            />
          </button>

          <button
            type="button"
            onClick={() => galleryRef.current?.click()}
            disabled={!canAddMore || isBusy}
            className={`relative flex min-h-[140px] flex-col justify-between rounded-3xl border p-4 text-left transition-all ${
              canAddMore && !isBusy
                ? "border-[var(--color-border)] bg-[var(--color-card)] hover:border-[var(--color-amber)]/40 hover:bg-[var(--color-surface)]"
                : "border-[var(--color-border)] bg-[var(--color-surface)] opacity-60"
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="rounded-2xl bg-[color-mix(in_srgb,var(--color-text-muted)_14%,transparent)] p-3 text-[var(--color-text-secondary)]">
                <FolderOpen size={22} />
              </div>
              {evidenceFiles.length > 0 && (
                <span className="rounded-full bg-white/80 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.2em] text-[var(--color-text-secondary)]">
                  {acceptedCountLabel}
                </span>
              )}
            </div>
            <div>
              <h3 className="text-sm font-semibold text-[var(--color-text-primary)]">Upload from Device</h3>
              <p className="mt-1 text-xs text-[var(--color-text-muted)]">Choose from Gallery</p>
              <p className="mt-2 text-xs text-[var(--color-text-secondary)]">Select existing photos or videos from your device.</p>
            </div>
            <input
              ref={galleryRef}
              type="file"
              accept={ACCEPT_ATTRIBUTE}
              multiple
              className="sr-only"
              onChange={(event) => {
                if (event.target.files?.length) {
                  handleFiles(event.target.files, "gallery");
                }
              }}
            />
          </button>
        </motion.div>
      ) : (
        <motion.div variants={itemVariants}>
          <div
            onDrop={(event) => {
              event.preventDefault();
              setIsDragging(false);
              if (event.dataTransfer.files.length) {
                handleFiles(event.dataTransfer.files, "drop");
              }
            }}
            onDragOver={(event) => {
              event.preventDefault();
              if (canAddMore) {
                setIsDragging(true);
              }
            }}
            onDragLeave={(event) => {
              event.preventDefault();
              setIsDragging(false);
            }}
            onClick={() => galleryRef.current?.click()}
            role="button"
            tabIndex={0}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                galleryRef.current?.click();
              }
            }}
            className={`group relative flex min-h-[250px] flex-col items-center justify-center gap-4 rounded-[1.75rem] border-2 border-dashed px-6 py-10 text-center transition-all ${
              isDragging
                ? "border-[var(--color-amber)] bg-[color-mix(in_srgb,var(--color-amber)_6%,transparent)] shadow-[var(--shadow-neu)]"
                : "border-[var(--color-border)] bg-[var(--color-surface)] hover:border-[var(--color-amber)] hover:bg-[var(--color-card)]"
            } ${!canAddMore ? "opacity-65" : ""}`}
          >
            <div className="flex h-20 w-20 items-center justify-center rounded-[1.75rem] bg-[color-mix(in_srgb,var(--color-amber)_12%,transparent)] text-[var(--color-amber)] transition-transform group-hover:scale-105">
              <Upload size={30} strokeWidth={1.8} />
            </div>
            <div className="space-y-2">
              <h3 className="text-base font-semibold text-[var(--color-text-primary)]">
                Drag photos or video, or tap to capture
              </h3>
              <p className="text-sm text-[var(--color-text-secondary)]">
                Drop files here or choose from your device. Accepts photos and video clips.
              </p>
              <p className="text-xs text-[var(--color-text-muted)]">
                Up to 5 files. Maximum 25 MB per file.
              </p>
            </div>
            <input
              ref={galleryRef}
              type="file"
              accept={ACCEPT_ATTRIBUTE}
              multiple
              className="sr-only"
              onChange={(event) => {
                if (event.target.files?.length) {
                  handleFiles(event.target.files, "gallery");
                }
              }}
            />
          </div>
        </motion.div>
      )}

      <motion.p variants={itemVariants} className="text-xs text-[var(--color-text-muted)]">
        Our AI will auto-detect the hazard type from your evidence.
      </motion.p>

      {analysisError && (
        <motion.div
          variants={itemVariants}
          className="flex items-start gap-2 rounded-2xl border border-[color-mix(in_srgb,var(--color-danger)_20%,transparent)] bg-[color-mix(in_srgb,var(--color-danger)_8%,transparent)] px-4 py-3"
        >
          <TriangleAlert size={16} className="mt-0.5 shrink-0 text-[var(--color-danger)]" />
          <p className="text-xs text-[var(--color-danger)]">{analysisError}</p>
        </motion.div>
      )}

      <AnimatePresence mode="popLayout">
        {evidenceFiles.length > 0 && (
          <motion.div variants={itemVariants} className="space-y-3">
            <div className="flex items-center justify-between gap-3">
              <p className="text-xs font-semibold uppercase tracking-[0.2em] text-[var(--color-text-muted)]">
                Uploaded Evidence
              </p>
              {!canAddMore && (
                <span className="rounded-full border border-[color-mix(in_srgb,var(--color-amber)_20%,transparent)] bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] px-3 py-1 text-[11px] font-medium text-[var(--color-amber)]">
                  Maximum 5 files reached
                </span>
              )}
            </div>
            <div className="grid grid-cols-3 gap-3 sm:grid-cols-3">
              {evidenceFiles.map((file) => (
                <motion.div
                  key={file.id}
                  layout
                  className="group relative overflow-hidden rounded-2xl border border-[var(--color-border)] bg-[var(--color-card)] shadow-sm"
                >
                  <div className="aspect-square bg-[var(--color-surface)]">
                    {file.previewUrl ? (
                      <img src={file.previewUrl} alt={file.name} className="h-full w-full object-cover" />
                    ) : file.mimeType.startsWith("video/") ? (
                      <div className="flex h-full items-center justify-center">
                        <FileVideo size={24} className="text-[var(--color-text-muted)]" />
                      </div>
                    ) : (
                      <div className="flex h-full items-center justify-center">
                        <FileImage size={24} className="text-[var(--color-text-muted)]" />
                      </div>
                    )}
                    <button
                      type="button"
                      onClick={() => onRemoveFile(file.id)}
                      className="absolute right-2 top-2 inline-flex h-8 w-8 items-center justify-center rounded-full bg-black/55 text-white backdrop-blur transition hover:bg-black/75"
                      aria-label={`Remove ${file.name}`}
                    >
                      <X size={14} />
                    </button>
                  </div>
                  <div className="space-y-1 px-3 py-2">
                    <p className="truncate text-[11px] font-medium text-[var(--color-text-primary)]">{file.name}</p>
                    <p className="text-[10px] text-[var(--color-text-muted)]">{formatFileSize(file.size)}</p>
                    {file.errorMessage ? (
                      <p className="text-[10px] font-medium text-[var(--color-danger)]">{file.errorMessage}</p>
                    ) : file.uploadStatus === "uploaded" ? (
                      <p className="text-[10px] font-medium text-[var(--color-success)]">Uploaded</p>
                    ) : file.uploadStatus === "uploading" ? (
                      <p className="text-[10px] font-medium text-[var(--color-amber)]">Uploading…</p>
                    ) : null}
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="space-y-3">
        <button
          type="button"
          onClick={onAnalyse}
          disabled={!hasFiles || isBusy}
          className={`flex h-12 w-full items-center justify-center gap-2 rounded-2xl font-semibold transition-all ${
            hasFiles && !isBusy ? "btn-amber" : "border border-[var(--color-border)] bg-[var(--color-surface)] text-[var(--color-text-muted)]"
          }`}
        >
          {analysisState === "scanning" || analysisState === "uploading" ? (
            <>
              <Sparkles size={16} className="animate-pulse" />
              Analysing…
            </>
          ) : (
            <>
              <Sparkles size={16} />
              Analyse with AI →
            </>
          )}
        </button>
        <p className="text-xs text-[var(--color-text-muted)]">
          {canAddMore
            ? "Your selected media stays in a single upload set."
            : "Maximum 5 files reached."}
        </p>
      </div>
    </motion.div>
  );
}

"use client";

import { motion } from "framer-motion";
import {
  AlertTriangle,
  Check,
  CircleHelp,
  Droplets,
  TreePine,
  Construction,
  TrafficCone,
  Sparkles,
} from "lucide-react";
import {
  HAZARD_OPTIONS,
  HAZARD_LABEL_BY_VALUE,
  SEVERITY_OPTIONS,
  type ReportAiAnalysisResult,
  type ReportFieldSuggestionState,
  type ReportHazardType,
  type ReportSeverityLevel,
} from "./reportTypes";

const HAZARD_ICONS: Record<ReportHazardType, React.ElementType> = {
  pothole: AlertTriangle,
  flooding: Droplets,
  fallenTree: TreePine,
  roadDebris: Construction,
  brokenSignal: TrafficCone,
  other: CircleHelp,
};

const severityLeftBorder: Record<ReportSeverityLevel, string> = {
  low: "border-l-[var(--color-success)]",
  medium: "border-l-[var(--color-amber)]",
  high: "border-l-orange-500",
  critical: "border-l-[var(--color-danger)]",
};

interface HazardInfoStepProps {
  hazardType: ReportHazardType | "";
  severity: ReportSeverityLevel | "";
  title: string;
  description: string;
  aiResult: ReportAiAnalysisResult | null;
  fieldSuggestions: ReportFieldSuggestionState;
  onHazardTypeChange: (value: ReportHazardType) => void;
  onSeverityChange: (value: ReportSeverityLevel) => void;
  onTitleChange: (value: string) => void;
  onDescriptionChange: (value: string) => void;
}

function AIBadge({ visible }: { visible: boolean }) {
  if (!visible) {
    return null;
  }

  return (
    <span className="inline-flex items-center gap-1 rounded-full border border-[color-mix(in_srgb,var(--color-amber)_18%,transparent)] bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.2em] text-[var(--color-amber)]">
      <Sparkles size={10} />
      AI suggested
    </span>
  );
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.05 } },
};

const itemVariants = {
  hidden: { opacity: 0, y: 12 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.28 } },
};

export function HazardInfoStep({
  hazardType,
  severity,
  title,
  description,
  aiResult,
  fieldSuggestions,
  onHazardTypeChange,
  onSeverityChange,
  onTitleChange,
  onDescriptionChange,
}: HazardInfoStepProps) {
  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className="space-y-6"
    >
      <motion.div variants={itemVariants}>
        <div className="mb-3 flex items-center justify-between gap-3">
          <label className="text-sm font-semibold text-[var(--color-text-primary)]">
            Hazard Type
          </label>
          <AIBadge visible={fieldSuggestions.hazardType === "ai"} />
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {HAZARD_OPTIONS.map((option) => {
            const Icon = HAZARD_ICONS[option.value];
            const isSelected = hazardType === option.value;
            const isSuggested = aiResult?.suggestedCategory === option.value && fieldSuggestions.hazardType === "ai";

            return (
              <button
                key={option.value}
                type="button"
                onClick={() => onHazardTypeChange(option.value)}
                aria-pressed={isSelected}
                className={`group relative flex min-h-[96px] flex-col items-start justify-between rounded-2xl border p-4 text-left transition-all ${
                  isSelected
                    ? "border-[var(--color-amber)] bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] shadow-[var(--shadow-neu)]"
                    : "border-[var(--color-border)] bg-[var(--color-card)] hover:border-[var(--color-amber)]/40 hover:bg-[var(--color-surface)]"
                }`}
              >
                <span className="flex w-full items-start justify-between gap-2">
                  <Icon
                    size={20}
                    className={isSelected ? "text-[var(--color-amber)]" : "text-[var(--color-text-muted)]"}
                    strokeWidth={1.8}
                  />
                  {isSelected && (
                    <span className="inline-flex h-6 w-6 items-center justify-center rounded-full bg-[var(--color-amber)] text-white shadow-sm">
                      <Check size={13} strokeWidth={3} />
                    </span>
                  )}
                </span>
                <div className="space-y-1.5">
                  <span className={`text-sm font-semibold ${isSelected ? "text-[var(--color-text-primary)]" : "text-[var(--color-text-secondary)]"}`}>
                    {option.label}
                  </span>
                  {isSuggested && <AIBadge visible />}
                </div>
                <div
                  className={`absolute inset-y-0 left-0 w-1 rounded-r-full bg-[var(--color-amber)] transition-opacity ${
                    isSelected ? "opacity-100" : "opacity-0"
                  }`}
                />
              </button>
            );
          })}
        </div>
      </motion.div>

      <motion.div variants={itemVariants}>
        <div className="mb-3 flex items-center justify-between gap-3">
          <label className="text-sm font-semibold text-[var(--color-text-primary)]">
            Severity Level
          </label>
          <AIBadge visible={fieldSuggestions.severity === "ai"} />
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {SEVERITY_OPTIONS.map((option) => {
            const isSelected = severity === option.value;
            const severityBadge = option.value === "low" ? "var(--color-success)" : option.value === "medium" ? "var(--color-amber)" : option.value === "high" ? "#f97316" : "var(--color-danger)";

            return (
              <button
                key={option.value}
                type="button"
                onClick={() => onSeverityChange(option.value)}
                aria-pressed={isSelected}
                className={`rounded-2xl border-l-4 p-3 text-left transition-all ${severityLeftBorder[option.value]} ${
                  isSelected
                    ? "border-[var(--color-amber)] bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] shadow-[var(--shadow-neu)]"
                    : "border border-[var(--color-border)] bg-[var(--color-card)] hover:border-[var(--color-amber)]/40 hover:bg-[var(--color-surface)]"
                }`}
              >
                <div className="flex items-center justify-between gap-2">
                  <span className={`text-sm font-semibold ${isSelected ? "text-[var(--color-text-primary)]" : "text-[var(--color-text-secondary)]"}`}>
                    {option.label}
                  </span>
                  <span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: severityBadge }} />
                </div>
                <p className="mt-1 text-[11px] text-[var(--color-text-muted)]">
                  {option.value === "low"
                    ? "Minor inconvenience"
                    : option.value === "medium"
                      ? "Moderate risk"
                      : option.value === "high"
                        ? "Significant danger"
                        : "Immediate threat"}
                </p>
