"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import { MapPin, Navigation, PencilLine, Sparkles, TriangleAlert } from "lucide-react";
import { ReportLocationMap } from "./ReportLocationMap";
import { reverseGeocodeLocation } from "./reportApi";
import type { ReportEvidenceFile, ReportLocationState } from "./reportTypes";

interface LocationStepProps {
  location: ReportLocationState;
  evidenceFiles: ReportEvidenceFile[];
  onLocationChange: (patch: Partial<ReportLocationState>) => void;
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.05 } },
};

const itemVariants = {
  hidden: { opacity: 0, y: 12 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.28 } },
};

function formatCoordinates(latitude: number, longitude: number): string {
  return `${latitude.toFixed(6)}, ${longitude.toFixed(6)}`;
}

export function LocationStep({ location, evidenceFiles, onLocationChange }: LocationStepProps) {
  const [isDetectingGps, setIsDetectingGps] = useState(false);
  const [geoError, setGeoError] = useState<string | null>(null);
  const [reverseLookupBusy, setReverseLookupBusy] = useState(false);

  const exifLocation = useMemo(
    () => evidenceFiles.find((file) => file.exifLocation)?.exifLocation ?? null,
    [evidenceFiles],
  );

  const applyCoordinates = useCallback(
    (latitude: number, longitude: number, locationMode: ReportLocationState["locationMode"]) => {
      onLocationChange({ latitude, longitude, locationMode });
    },
    [onLocationChange],
  );

  const detectGpsLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setGeoError("Geolocation is not supported by your browser.");
      return;
    }

    setIsDetectingGps(true);
    setGeoError(null);

    navigator.geolocation.getCurrentPosition(
      (position) => {
        applyCoordinates(position.coords.latitude, position.coords.longitude, "gps");
        setIsDetectingGps(false);
      },
      (error) => {
        setIsDetectingGps(false);
        switch (error.code) {
          case error.PERMISSION_DENIED:
            setGeoError("Location access denied. You can still drop the pin manually.");
            break;
          case error.POSITION_UNAVAILABLE:
            setGeoError("Location unavailable. Try again or drag the marker.");
            break;
          case error.TIMEOUT:
            setGeoError("Location request timed out. Please try again.");
            break;
          default:
            setGeoError("Unable to detect your location.");
        }
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 60000 },
    );
  }, [applyCoordinates]);

  useEffect(() => {
    if (location.latitude == null || location.longitude == null) {
      detectGpsLocation();
    }
  }, [detectGpsLocation, location.latitude, location.longitude]);

  useEffect(() => {
    if (location.latitude == null || location.longitude == null) {
      return;
    }

    let active = true;
    setReverseLookupBusy(true);
    const latitude = location.latitude;
    const longitude = location.longitude;

    const timer = setTimeout(() => {
      reverseGeocodeLocation({ latitude, longitude })
        .then((result) => {
          if (!active || !result) {
            return;
          }

          onLocationChange({
            address: result.label,
            locationMode: location.locationMode === "manual" ? "manual" : location.locationMode,
          });
        })
        .finally(() => {
          if (active) {
            setReverseLookupBusy(false);
          }
        });
    }, 400);

    return () => {
      active = false;
      clearTimeout(timer);
    };
  }, [location.latitude, location.longitude, location.locationMode, onLocationChange]);

  const selectedExifLocation = useMemo(() => location.exifLocation ?? exifLocation, [exifLocation, location.exifLocation]);

  return (
    <motion.div variants={containerVariants} initial="hidden" animate="visible" className="space-y-6">
      <motion.div variants={itemVariants} className="space-y-3">
        <div className="flex items-center justify-between gap-3">
          <label className="text-sm font-semibold text-[var(--color-text-primary)]">Location</label>
          {reverseLookupBusy && (
            <span className="inline-flex items-center gap-1 rounded-full bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.2em] text-[var(--color-amber)]">
              <Sparkles size={10} />
              Resolving address
            </span>
          )}
        </div>

        <div className="overflow-hidden rounded-[1.75rem] border border-[var(--color-border)] bg-[var(--color-surface)] shadow-[var(--shadow-neu)]">
          <div className="h-[350px] w-full">
            {location.latitude != null && location.longitude != null ? (
              <ReportLocationMap
                latitude={location.latitude}
                longitude={location.longitude}
                onChange={(latitude, longitude) => applyCoordinates(latitude, longitude, location.locationMode === "manual" ? "manual" : "gps")}
              />
            ) : (
              <div className="flex h-full items-center justify-center px-6 text-center">
                <div className="space-y-3">
                  <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-2xl bg-[color-mix(in_srgb,var(--color-amber)_12%,transparent)] text-[var(--color-amber)]">
                    <MapPin size={28} />
                  </div>
                  <p className="text-sm font-medium text-[var(--color-text-primary)]">Waiting for GPS or EXIF coordinates</p>
                  <button
                    type="button"
                    onClick={detectGpsLocation}
                    className="btn-outline inline-flex items-center gap-2 px-4 py-2 text-sm"
                  >
                    <Navigation size={16} />
                    Detect my location
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </motion.div>

      {geoError && (
        <motion.div
          variants={itemVariants}
          className="flex items-start gap-2 rounded-2xl border border-[color-mix(in_srgb,var(--color-danger)_20%,transparent)] bg-[color-mix(in_srgb,var(--color-danger)_8%,transparent)] px-4 py-3"
        >
          <TriangleAlert size={16} className="mt-0.5 shrink-0 text-[var(--color-danger)]" />
          <p className="text-xs text-[var(--color-danger)]">{geoError}</p>
        </motion.div>
      )}

      <motion.div variants={itemVariants} className="grid gap-3 sm:grid-cols-2">
        <div className="rounded-2xl border border-[var(--color-border)] bg-[var(--color-card)] p-4">
          <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--color-text-muted)]">Resolved Address</p>
          <p className="mt-2 text-sm text-[var(--color-text-primary)]">{location.address || "Resolving address from the selected pin…"}</p>
          {location.latitude != null && location.longitude != null && (
            <p className="mt-3 text-xs text-[var(--color-text-muted)] font-mono">{formatCoordinates(location.latitude, location.longitude)}</p>
          )}
        </div>

        <div className="rounded-2xl border border-[var(--color-border)] bg-[var(--color-card)] p-4">
          <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-[var(--color-text-muted)]">Location source</p>
          <div className="mt-3 flex flex-wrap gap-2">
            <button
              type="button"
              onClick={detectGpsLocation}
              className={`rounded-full border px-3 py-2 text-xs font-medium transition-colors ${
                location.locationMode === "gps"
                  ? "border-[var(--color-amber)] bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] text-[var(--color-text-primary)]"
                  : "border-[var(--color-border)] bg-[var(--color-surface)] text-[var(--color-text-secondary)]"
              }`}
            >
              Auto GPS
            </button>
            {selectedExifLocation && (
              <button
                type="button"
                onClick={() => {
                  onLocationChange({
                    latitude: selectedExifLocation.latitude,
                    longitude: selectedExifLocation.longitude,
                    address: selectedExifLocation.address ?? location.address,
                    locationMode: "exif",
                    useExifLocation: true,
                    exifLocation: selectedExifLocation,
                  });
                }}
                className={`rounded-full border px-3 py-2 text-xs font-medium transition-colors ${
                  location.locationMode === "exif"
                    ? "border-[var(--color-amber)] bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] text-[var(--color-text-primary)]"
                    : "border-[var(--color-border)] bg-[var(--color-surface)] text-[var(--color-text-secondary)]"
                }`}
              >
                Use photo EXIF location
              </button>
            )}
            <button
              type="button"
              onClick={() => onLocationChange({ locationMode: "manual" })}
              className={`rounded-full border px-3 py-2 text-xs font-medium transition-colors ${
                location.locationMode === "manual"
                  ? "border-[var(--color-amber)] bg-[color-mix(in_srgb,var(--color-amber)_10%,transparent)] text-[var(--color-text-primary)]"
                  : "border-[var(--color-border)] bg-[var(--color-surface)] text-[var(--color-text-secondary)]"
              }`}
            >
              Manual pin
            </button>
          </div>
        </div>
      </motion.div>

      <motion.div variants={itemVariants} className="rounded-2xl border border-[var(--color-border)] bg-[var(--color-card)] p-4">
        <label htmlFor="report-landmark" className="mb-2 block text-sm font-semibold text-[var(--color-text-primary)]">
          Landmark override
        </label>
        <div className="relative">
          <PencilLine size={16} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" />
          <input
            id="report-landmark"
            type="text"
            value={location.landmark}
            onChange={(event) => onLocationChange({ landmark: event.target.value })}
            placeholder="Nearby landmark, shop, or junction"
            className="w-full rounded-2xl border border-[var(--color-border)] bg-[var(--color-surface)] py-3 pl-10 pr-4 text-sm text-[var(--color-text-primary)] placeholder:text-[var(--color-text-muted)] focus:border-[var(--color-amber)] focus:outline-none focus:ring-2 focus:ring-[color-mix(in_srgb,var(--color-amber)_24%,transparent)]"
          />
        </div>
        <p className="mt-2 text-xs text-[var(--color-text-muted)]">
          {location.locationMode === "exif"
            ? "The map is using location metadata embedded in your photo."
            : "Drag the pin to fine-tune the location if needed."}
        </p>
      </motion.div>
    </motion.div>
  );
}

import type {
  ReportAiAnalysisResult,
  ReportHazardType,
  ReportSeverityLevel,
  ReportBackendCategory,
  ReportBackendSeverity,
} from "./reportTypes";
import { fetchCitizenAuth, readResponseJson, extractMessage } from "@/lib/auth/citizenSession";

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL ?? "";

export interface UploadMediaResponseItem {
  mediaId: string;
  url: string;
  key: string;
  size: number;
  mimeType: string;
  width?: number;
  height?: number;
  duration?: number;
}

export interface AiDetectResponse {
  suggestedCategory: ReportBackendCategory | null;
  suggestedSeverity: ReportBackendSeverity | null;
  confidence: number | null;
  allDetectedIssues: string[];
  totalDetected: number;
  inferenceMs: number;
  annotatedImage: {
    url: string;
    expiresIn: number;
    s3Key: string;
  } | null;
  message: string;
}

export interface ComplaintSubmissionInput {
  category: ReportBackendCategory;
  latitude: number;
  longitude: number;
  mediaIds: string[];
  description?: string;
  suggestedFix?: string;
  roadName?: string;
  roadNumber?: string;
  landmark?: string;
  direction?: string;
  isAnonymous?: boolean;
  aiCategory?: ReportBackendCategory | null;
  aiConfidence?: number | null;
  aiRawResult?: Record<string, unknown> | null;
  /** S3 key for the annotated result image — stored permanently, no re-upload needed. */
  aiAnnotatedImageKey?: string | null;
}

export interface ComplaintSubmissionResponse {
  id: string;
  ticketNumber: string;
}

export interface ReverseGeocodeResult {
  label: string;
  roadName?: string | null;
  city?: string | null;
  state?: string | null;
  country?: string | null;
}

function apiUrl(path: string): string {
  return `${API_BASE_URL}/api${path}`;
}

export async function uploadReportMedia(params: {
  files: File[];
  accessToken: string | null;
}): Promise<UploadMediaResponseItem[]> {
  const formData = new FormData();
  for (const file of params.files) {
    formData.append("files", file);
  }

  const response = await fetchCitizenAuth(apiUrl("/upload"), {
    method: "POST",
    body: formData,
  });

  const payload = await readResponseJson(response) as { success?: boolean; data?: { media?: UploadMediaResponseItem[] } };
  if (!response.ok) {
    throw new Error(extractMessage(payload, "Unable to upload evidence. Please try again."));
  }

  const media = payload.data?.media ?? [];
  if (media.length === 0) {
    throw new Error("Unable to upload evidence. Please try again.");
  }

  return media;
}

export async function analyzeReportMedia(params: {
  fileId: string;
  accessToken: string | null;
}): Promise<ReportAiAnalysisResult> {
  const response = await fetchCitizenAuth(apiUrl("/ai/detect"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ fileId: params.fileId }),
  });

  const payload = await readResponseJson(response) as { success?: boolean; data?: AiDetectResponse; error?: { message?: string }; message?: string };

  if (!response.ok) {
    throw new Error(extractMessage(payload, "AI analysis is temporarily unavailable."));
  }

  const data = payload.data;
  if (!data) {
    throw new Error("AI analysis is temporarily unavailable.");
  }
  return {
    suggestedCategory: data.suggestedCategory as ReportAiAnalysisResult["suggestedCategory"],
    suggestedSeverity: data.suggestedSeverity as ReportAiAnalysisResult["suggestedSeverity"],
    confidence: data.confidence,
    allDetectedIssues: data.allDetectedIssues ?? [],
    totalDetected: data.totalDetected ?? 0,
    inferenceMs: data.inferenceMs ?? 0,
    annotatedImage: data.annotatedImage ?? null,
    message: data.message ?? "AI analysis completed.",
  };
}

export async function submitRoadHazardReport(params: {
  payload: ComplaintSubmissionInput;
  accessToken: string | null;
}): Promise<ComplaintSubmissionResponse> {
  // Hard 60-second deadline — the complaint submission path includes AI
  // inference, PostGIS authority lookup, S3 annotation upload, and queue
  // enqueue jobs. The backend keepAliveTimeout is 65 s, so this fires first
  // and gives a clean user-facing error rather than an ECONNRESET.
  const abort = new AbortController();
  const timeoutId = setTimeout(() => abort.abort(), 60_000);

  // Log the payload shape so we can catch field-shape mismatches quickly.
  console.debug("[submitRoadHazardReport] payload →", JSON.stringify(params.payload, null, 2));

  let response: Response;
  try {
    response = await fetchCitizenAuth(apiUrl("/complaints"), {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(params.payload),
      signal: abort.signal,
    });
  } catch (err) {
    if (err instanceof DOMException && err.name === "AbortError") {
      throw new Error("Request timed out after 60 seconds. Please try again.");
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }

  const payload = await readResponseJson(response) as {
    success?: boolean;
    data?: ComplaintSubmissionResponse;
    error?: { message?: string };
    message?: string;
  };

  if (!response.ok) {
    const msg = extractMessage(payload, "Unable to submit your report. Please try again.");
    console.error("[submitRoadHazardReport] API error →", response.status, msg, payload);
    throw new Error(msg);
  }

  if (!payload.data?.id || !payload.data.ticketNumber) {
    console.error("[submitRoadHazardReport] Unexpected response shape →", payload);
    throw new Error("Unable to submit your report. Please try again.");
  }

  return payload.data;
}

export async function reverseGeocodeLocation(params: {
  latitude: number;
  longitude: number;
}): Promise<ReverseGeocodeResult | null> {
  const url = new URL("https://nominatim.openstreetmap.org/reverse");
  url.searchParams.set("format", "jsonv2");
  url.searchParams.set("lat", String(params.latitude));
  url.searchParams.set("lon", String(params.longitude));
  url.searchParams.set("zoom", "18");
  url.searchParams.set("addressdetails", "1");

  const response = await fetch(url.toString(), {
    headers: {
      Accept: "application/json",
    },
  });

  if (!response.ok) {
    return null;
  }

  const payload = (await response.json()) as {
    display_name?: string;
    address?: {
      road?: string;
      neighbourhood?: string;
      suburb?: string;
      city?: string;
      town?: string;
      village?: string;
      state?: string;
      country?: string;
    };
  };

  const label = payload.display_name ?? "Dropped pin";
  return {
    label,
    roadName: payload.address?.road ?? payload.address?.neighbourhood ?? payload.address?.suburb ?? null,
    city: payload.address?.city ?? payload.address?.town ?? payload.address?.village ?? null,
    state: payload.address?.state ?? null,
    country: payload.address?.country ?? null,
  };
}

