      <aside
        style={{ width: SIDEBAR_WIDTH }}
        className={`hidden lg:flex lg:flex-col lg:shrink-0 border-r h-screen sticky top-0 ${sidebarShell}`}
      >
        {sidebarContent}
      </aside>
    </>
  );
}

