export function getInitialView(config: MapConfig): { center: [number, number]; zoom: number } {
  if (config.defaultLevel === 'national') {
    return { center: [20.5937, 78.9629], zoom: 5 };
  }

  if (config.defaultRegionId) {
    const stateCenter = STATE_CENTERS[config.defaultRegionId];
    if (stateCenter) {
      return { center: stateCenter, zoom: 7 };
    }

    const districtCenter = DISTRICT_CENTERS[config.defaultRegionId];
    if (districtCenter) {
      return { center: districtCenter, zoom: 10 };
    }
  }

  return { center: [20.5937, 78.9629], zoom: 5 };
}

export function generateTooltipHTML(stats: RegionStats, isDark: boolean): string {
  const bg = isDark ? '#222838' : '#FFFFFF';
  const textPrimary = isDark ? '#EDF1F7' : '#1C2B3A';
  const textSecondary = isDark ? '#A8B6C8' : '#4A5D70';
  const textMuted = isDark ? '#5C6E82' : '#8A9BAD';
  const border = isDark ? '#313A50' : '#D6DFE8';
  const riskColor = getRiskColor(stats.riskScore);
  const riskLabel = getRiskLabel(stats.riskScore);

  const trendIcon = stats.trend === 'up' ? '📈' : stats.trend === 'down' ? '📉' : '➡️';
  const trendSign = stats.trend === 'up' ? '+' : stats.trend === 'down' ? '-' : '';

  return `
    <div style="
      background: ${bg};
      border: 1px solid ${border};
      border-radius: 12px;
      padding: 12px 14px;
      max-width: 220px;
      box-shadow: 0 8px 32px rgba(0,0,0,0.18);
      font-family: system-ui, -apple-system, sans-serif;
      font-size: 11px;
      line-height: 1.4;
      color: ${textPrimary};
    ">
      <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span style="
          display: inline-block;
          padding: 2px 7px;
          border-radius: 6px;
          background: ${riskColor}22;
          color: ${riskColor};
          font-size: 9px;
          font-weight: 700;
          text-transform: uppercase;
          letter-spacing: 0.5px;
        ">${riskLabel}</span>
      </div>
      <div style="font-weight: 700; font-size: 13px; margin-bottom: 8px; color: ${textPrimary};">${stats.name}</div>
      <div style="border-top: 1px solid ${border}; margin-bottom: 8px;"></div>
      <div style="color: ${textSecondary}; margin-bottom: 3px;">📊 ${stats.totalReports} Total Reports</div>
      <div style="color: ${textSecondary}; margin-bottom: 3px;">🔴 Critical: ${stats.criticalCount} &nbsp; 🟡 High: ${stats.highCount}</div>
      <div style="color: ${textSecondary}; margin-bottom: 8px;">🟢 Resolved: ${stats.resolvedReports} &nbsp; ⏳ Open: ${stats.openReports}</div>
      <div style="border-top: 1px solid ${border}; margin-bottom: 8px;"></div>
      <div style="color: ${textMuted}; margin-bottom: 3px;">⚠️ Top: ${stats.topHazardType} &nbsp; ${trendIcon} ${trendSign}${stats.trendPercent}%</div>
      <div style="color: ${textMuted};">✅ ${stats.verificationAccuracy}% accuracy &nbsp; ⏱ ${stats.avgResolutionDays}d avg</div>
    </div>
  `;
}

export function generateFallbackGeoJSON(
  center: [number, number],
  regionCount: number,
  regionNames: string[]
): GeoJSON.FeatureCollection {
  const features: GeoJSON.Feature[] = regionNames.map((name, i) => {
    const angle = (2 * Math.PI * i) / regionCount;
    const radius = 0.8 + Math.random() * 0.5;
    const lat = center[0] + radius * Math.cos(angle);
    const lng = center[1] + radius * Math.sin(angle);
    const size = 0.3 + Math.random() * 0.2;

    return {
      type: 'Feature',
      properties: {
        name: name,
        NAME_1: name,
      },
      geometry: {
        type: 'Polygon',
        coordinates: [[
          [lng - size, lat - size],
          [lng + size, lat - size],
          [lng + size, lat + size],
          [lng - size, lat + size],
          [lng - size, lat - size],
        ]],
      },
    };
  });

  return {
    type: 'FeatureCollection',
    features,
  };
}

import type { HazardType, MapLevel, RegionStats, RiskLevel, Trend } from './types';

const HAZARD_TYPES: HazardType[] = ['Pothole', 'Flooding', 'Accident', 'Debris', 'Signal'];

function getRiskLevel(score: number): RiskLevel {
  if (score >= 80) return 'very_high';
  if (score >= 60) return 'high';
  if (score >= 40) return 'medium';
  if (score >= 20) return 'low';
  return 'very_low';
}

function deterministicHash(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash + str.charCodeAt(i)) & 0x7fffffff;
  }
  return hash;
}

function seededRandom(seed: number): () => number {
  let s = seed;
  return () => {
    s = (s * 1664525 + 1013904223) & 0x7fffffff;
    return s / 0x7fffffff;
  };
}

function createRegionStats(
  id: string,
  name: string,
  level: MapLevel,
  riskScore: number,
  totalReports: number,
  parentId?: string,
  parentName?: string
): RegionStats {
  const rand = seededRandom(deterministicHash(id));
  const openRatio = 0.15 + rand() * 0.25;
  const resolvedRatio = 0.5 + rand() * 0.3;
  const pendingRatio = 1 - openRatio - resolvedRatio;

  const openReports = Math.round(totalReports * openRatio);
  const resolvedReports = Math.round(totalReports * resolvedRatio);
  const pendingReports = Math.max(0, totalReports - openReports - resolvedReports);

  const criticalRatio = riskScore > 70 ? 0.1 + rand() * 0.1 : 0.03 + rand() * 0.05;
  const highRatio = 0.15 + rand() * 0.15;
  const mediumRatio = 0.3 + rand() * 0.15;

  const criticalCount = Math.round(totalReports * criticalRatio);
  const highCount = Math.round(totalReports * highRatio);
  const mediumCount = Math.round(totalReports * mediumRatio);
  const lowCount = Math.max(0, totalReports - criticalCount - highCount - mediumCount);

  const trends: Trend[] = ['up', 'down', 'stable'];
  const trend = trends[Math.floor(rand() * 3)];

  return {
    id,
    name,
    level,
    parentId,
    parentName,
    totalReports,
    openReports,
    resolvedReports,
    pendingReports,
    criticalCount,
    highCount,
    mediumCount,
    lowCount,
    verificationAccuracy: Math.round(75 + rand() * 22),
    avgResolutionDays: Math.round((1.5 + rand() * 6) * 10) / 10,
    topHazardType: HAZARD_TYPES[Math.floor(rand() * 5)],
    riskScore,
    riskLevel: getRiskLevel(riskScore),
    lastReportedAt: new Date(Date.now() - Math.floor(rand() * 86400000 * 3)).toISOString(),
    trend,
    trendPercent: Math.round(rand() * 25),
  };
}

