  | "Approved"
  | "Rejected"
  | "Clarification Requested";

export type TicketStatus = "Open" | "In Progress" | "Overdue" | "Completed";
export type TicketPriority = "Critical" | "High" | "Medium" | "Low";

export interface TicketTimelineStep {
  label: string;
  time: string;
  done: boolean;
}

export interface TicketMaterial {
